struct LanguageChoice {
    UiLanguage value;
    const wchar_t* key;
    const wchar_t* supportUrl;
    bool rtl;
};

static constexpr LanguageChoice kLanguageChoices[] = {
    {UiLanguage::Automatic, L"automatic", L"", false},
    {UiLanguage::English, L"en-us", L"https://support.microsoft.com/en-us/support/", false},
    {UiLanguage::French, L"fr-fr", L"https://support.microsoft.com/fr-fr/support/", false},
    {UiLanguage::Italian, L"it-it", L"https://support.microsoft.com/it-it/support/", false},
    {UiLanguage::German, L"de-de", L"https://support.microsoft.com/de-de/support/", false},
    {UiLanguage::ChineseSimplified, L"zh-cn", L"https://support.microsoft.com/zh-cn/support/", false},
    {UiLanguage::ChineseTraditional, L"zh-tw", L"https://support.microsoft.com/zh-tw/support/", false},
    {UiLanguage::Hindi, L"hi-in", L"https://support.microsoft.com/hi-in/support/", false},
    {UiLanguage::Japanese, L"ja-jp", L"https://support.microsoft.com/ja-jp/support/", false},
    {UiLanguage::Korean, L"ko-kr", L"https://support.microsoft.com/ko-kr/support/", false},
    {UiLanguage::Dutch, L"nl-nl", L"https://support.microsoft.com/nl-nl/support/", false},
    {UiLanguage::Russian, L"ru-ru", L"https://support.microsoft.com/ru-ru/support/", false},
    {UiLanguage::Turkish, L"tr-tr", L"https://support.microsoft.com/tr-tr/support/", false},
    {UiLanguage::Arabic, L"ar-sa", L"https://support.microsoft.com/ar-sa/support/", true},
    {UiLanguage::Spanish, L"es-es", L"https://support.microsoft.com/es-es/support/", false},
};

static UiLanguage g_activeLanguage = UiLanguage::English;

static size_t LanguageRow(UiLanguage language) noexcept {
    const int value = static_cast<int>(language);
    if (value <= static_cast<int>(UiLanguage::Automatic) ||
        value > static_cast<int>(UiLanguage::Spanish)) {
        return 0;
    }
    return static_cast<size_t>(value - 1);
}

static const wchar_t* Ui(UiText id) noexcept {
    const size_t index = static_cast<size_t>(id);
    if (index >= static_cast<size_t>(UiText::Count)) {
        return L"";
    }
    return kUiStrings[LanguageRow(g_activeLanguage)][index];
}

static const TaskText& LocalizedTaskText(TaskTextId id) noexcept {
    size_t index = static_cast<size_t>(id);
    if (index >= static_cast<size_t>(TaskTextId::Count)) {
        index = 0;
    }
    return kTaskStrings[LanguageRow(g_activeLanguage)][index];
}

static const CreditText& LocalizedCreditText() noexcept {
    return kCreditStrings[LanguageRow(g_activeLanguage)];
}

static bool IsRtlLanguage() noexcept {
    for (const auto& choice : kLanguageChoices) {
        if (choice.value == g_activeLanguage) {
            return choice.rtl;
        }
    }
    return false;
}

static UiLanguage ResolveAutomaticLanguage() noexcept {
    const LANGID id = GetUserDefaultUILanguage();
    switch (PRIMARYLANGID(id)) {
        case LANG_FRENCH: return UiLanguage::French;
        case LANG_ITALIAN: return UiLanguage::Italian;
        case LANG_GERMAN: return UiLanguage::German;
        case LANG_CHINESE:
            switch (SUBLANGID(id)) {
                case SUBLANG_CHINESE_TRADITIONAL:
                case SUBLANG_CHINESE_HONGKONG:
                case SUBLANG_CHINESE_MACAU:
                    return UiLanguage::ChineseTraditional;
                default:
                    return UiLanguage::ChineseSimplified;
            }
        case LANG_HINDI: return UiLanguage::Hindi;
        case LANG_JAPANESE: return UiLanguage::Japanese;
        case LANG_KOREAN: return UiLanguage::Korean;
        case LANG_DUTCH: return UiLanguage::Dutch;
        case LANG_RUSSIAN: return UiLanguage::Russian;
        case LANG_TURKISH: return UiLanguage::Turkish;
        case LANG_ARABIC: return UiLanguage::Arabic;
        case LANG_SPANISH: return UiLanguage::Spanish;
        default: return UiLanguage::English;
    }
}

static LANGID ActiveLanguageId() noexcept {
    switch (g_activeLanguage) {
        case UiLanguage::French: return MAKELANGID(LANG_FRENCH, SUBLANG_DEFAULT);
        case UiLanguage::Italian: return MAKELANGID(LANG_ITALIAN, SUBLANG_DEFAULT);
        case UiLanguage::German: return MAKELANGID(LANG_GERMAN, SUBLANG_DEFAULT);
        case UiLanguage::ChineseSimplified:
            return MAKELANGID(LANG_CHINESE, SUBLANG_CHINESE_SIMPLIFIED);
        case UiLanguage::ChineseTraditional:
            return MAKELANGID(LANG_CHINESE, SUBLANG_CHINESE_TRADITIONAL);
        case UiLanguage::Hindi: return MAKELANGID(LANG_HINDI, SUBLANG_DEFAULT);
        case UiLanguage::Japanese: return MAKELANGID(LANG_JAPANESE, SUBLANG_DEFAULT);
        case UiLanguage::Korean: return MAKELANGID(LANG_KOREAN, SUBLANG_DEFAULT);
        case UiLanguage::Dutch: return MAKELANGID(LANG_DUTCH, SUBLANG_DEFAULT);
        case UiLanguage::Russian: return MAKELANGID(LANG_RUSSIAN, SUBLANG_DEFAULT);
        case UiLanguage::Turkish: return MAKELANGID(LANG_TURKISH, SUBLANG_DEFAULT);
        case UiLanguage::Arabic: return MAKELANGID(LANG_ARABIC, SUBLANG_DEFAULT);
        case UiLanguage::Spanish: return MAKELANGID(LANG_SPANISH, SUBLANG_DEFAULT);
        case UiLanguage::Automatic:
        case UiLanguage::English:
        default:
            return MAKELANGID(LANG_ENGLISH, SUBLANG_ENGLISH_US);
    }
}

static bool TryParseUiLanguage(const wchar_t* key,
                               UiLanguage* language) noexcept {
    if (!key || !language) {
        return false;
    }
    for (const auto& choice : kLanguageChoices) {
        if (EqualsIgnoreCase(key, choice.key)) {
            *language = choice.value;
            return true;
        }
    }
    return false;
}

static UiLanguage ResolveUiLanguage(UiLanguage requested) noexcept {
    return requested == UiLanguage::Automatic ? ResolveAutomaticLanguage()
                                                : requested;
}

static const wchar_t* LocalizedSupportUrl() noexcept {
    for (const auto& choice : kLanguageChoices) {
        if (choice.value == g_activeLanguage && choice.supportUrl[0]) {
            return choice.supportUrl;
        }
    }
    return L"https://support.microsoft.com/en-us/support/";
}

static int UiMessageBox(HWND owner, const wchar_t* text,
                        const wchar_t* caption, UINT type) {
    if (IsRtlLanguage()) {
        type |= MB_RTLREADING | MB_RIGHT;
    }
    // Let native OK/Yes/No controls follow a manual interface-language
    // override when the corresponding Windows MUI resources are installed.
    const LANGID previous = GetThreadUILanguage();
    const LANGID desired = ActiveLanguageId();
    const bool changeThreadLanguage = desired != 0 && desired != previous;
    const LANGID applied =
        changeThreadLanguage ? SetThreadUILanguage(desired) : desired;
    const int result = MessageBoxW(owner, text, caption, type);
    if (changeThreadLanguage && applied != 0 && previous != 0) {
        SetThreadUILanguage(previous);
    }
    return result;
}


static void TrimInPlace(wchar_t* s) {
    if (!s) {
        return;
    }
    wchar_t* start = s;
    while (*start == L' ' || *start == L'\t') {
        ++start;
    }
    if (start != s) {
        memmove(s, start, (wcslen(start) + 1) * sizeof(wchar_t));
    }
    size_t n = wcslen(s);
    while (n > 0 && (s[n - 1] == L' ' || s[n - 1] == L'\t')) {
        s[--n] = 0;
    }
}

static UINT GetWndDpi(HWND hwnd) {
    using Fn = UINT(WINAPI*)(HWND);
    static Fn p = reinterpret_cast<Fn>(
        GetProcAddress(GetModuleHandleW(L"user32.dll"), "GetDpiForWindow"));
    if (p && hwnd) {
        const UINT dpi = p(hwnd);
        if (dpi) {
            return dpi;
        }
    }
    HDC dc = GetDC(nullptr);
    int dpi = 96;
    if (dc) {
        dpi = GetDeviceCaps(dc, LOGPIXELSX);
        ReleaseDC(nullptr, dc);
    }
    return dpi > 0 ? static_cast<UINT>(dpi) : 96;
}

static int ScalePx(int px, UINT dpi) {
    return MulDiv(px, static_cast<int>(dpi), 96);
}

static HFONT MakeFont(const wchar_t* face, int pointTenths, UINT dpi, int weight,
                      bool italic = false) {
    LOGFONTW lf{};
    lf.lfHeight = -MulDiv(pointTenths, static_cast<int>(dpi), 720);
    lf.lfWeight = weight;
    lf.lfItalic = italic ? TRUE : FALSE;
    lf.lfCharSet = DEFAULT_CHARSET;
    lf.lfQuality = CLEARTYPE_QUALITY;
    CopyTrunc(lf.lfFaceName, LF_FACESIZE, face);
    return CreateFontIndirectW(&lf);
}

// ---------------------------------------------------------------------------
// Version detection (RtlGetVersion isolated)
// ---------------------------------------------------------------------------

namespace Undoc {
// Isolated undocumented helper. See file header.
static bool RtlGetVersion(OSVERSIONINFOW* vi) {
    if (!vi) {
        return false;
    }
    using Fn = LONG(WINAPI*)(OSVERSIONINFOW*);
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    if (!ntdll) {
        return false;
    }
    const auto fn = reinterpret_cast<Fn>(GetProcAddress(ntdll, "RtlGetVersion"));
    if (!fn) {
        return false;
    }
    vi->dwOSVersionInfoSize = sizeof(*vi);
    return fn(vi) == 0;
}

// Isolated. Copies the current user's tile to a temp path. NULL username =
// the calling user. Flag 0x80000000 creates the pictures dir if needed.
static bool SHGetUserPicturePath(wchar_t* path, UINT cch) {
    if (!path || cch == 0) {
        return false;
    }
    path[0] = 0;
    HMODULE sh = GetModuleHandleW(L"shell32.dll");
    if (!sh) {
        sh = LoadLibraryW(L"shell32.dll");
    }
    if (!sh) {
        return false;
    }
    using Fn = HRESULT(WINAPI*)(LPCWSTR, DWORD, LPWSTR, UINT);
    const auto fn = reinterpret_cast<Fn>(GetProcAddress(sh, (LPCSTR)261));
    if (!fn) {
        return false;
    }
    return SUCCEEDED(fn(nullptr, 0x80000000, path, cch)) && path[0] != 0;
}
}  // namespace Undoc

struct OsInfo {
    DWORD major = 0;
    DWORD minor = 0;
    DWORD build = 0;
    DWORD productType = 0;
    wchar_t displayVersion[32] = {};
    wchar_t productName[64] = {};
    wchar_t edition[64] = {};
    bool isWin11 = false;
    bool ok = false;
};

static const wchar_t* EditionFromProduct(DWORD product) {
    switch (product) {
        case PRODUCT_ULTIMATE:
            return L"Ultimate";
        case PRODUCT_ULTIMATE_N:
            return L"Ultimate N";
        case PRODUCT_HOME_BASIC:
            return L"Home Basic";
        case PRODUCT_HOME_BASIC_N:
            return L"Home Basic N";
        case PRODUCT_HOME_PREMIUM:
            return L"Home Premium";
        case PRODUCT_HOME_PREMIUM_N:
            return L"Home Premium N";
        case PRODUCT_ENTERPRISE:
            return L"Enterprise";
        case PRODUCT_ENTERPRISE_N:
            return L"Enterprise N";
        case PRODUCT_ENTERPRISE_S:
            return L"Enterprise LTSC";
        case PRODUCT_ENTERPRISE_S_N:
            return L"Enterprise LTSC N";
        case PRODUCT_EDUCATION:
            return L"Education";
        case PRODUCT_EDUCATION_N:
            return L"Education N";
        case PRODUCT_PROFESSIONAL:
            return L"Pro";
        case PRODUCT_PROFESSIONAL_N:
            return L"Pro N";
        case PRODUCT_PROFESSIONAL_WMC:
            return L"Pro with Media Center";
        case PRODUCT_BUSINESS:
            return L"Business";
        case PRODUCT_STARTER:
            return L"Starter";
        case PRODUCT_STARTER_N:
            return L"Starter N";
        case PRODUCT_CORE:
            return L"Home";
        case PRODUCT_CORE_N:
            return L"Home N";
        case PRODUCT_CORE_SINGLELANGUAGE:
            return L"Home Single Language";
        case PRODUCT_CORE_COUNTRYSPECIFIC:
            return L"Home China";
        case PRODUCT_IOTUAP:
            return L"IoT";
        case 0x000000BC:  // PRODUCT_IOTENTERPRISE
            return L"IoT Enterprise";
        case 0x000000AF:  // PRODUCT_SERVERRDSH
            return L"Enterprise multi-session";
        case 0x000000B2:  // PRODUCT_CLOUD
            return L"S";
        case 0x000000A1:  // PRODUCT_PRO_WORKSTATION
            return L"Pro for Workstations";
        case 0x000000A2:
            return L"Pro for Workstations N";
        case PRODUCT_STANDARD_SERVER:
            return L"Standard";
        case PRODUCT_DATACENTER_SERVER:
            return L"Datacenter";
        default:
            return L"";
    }
}

static bool ReadRegSz(HKEY root, const wchar_t* sub, const wchar_t* value,
                      wchar_t* buf, size_t cch) {
    if (!buf || cch == 0) {
        return false;
    }
    buf[0] = 0;
    HKEY key = nullptr;
    if (RegOpenKeyExW(root, sub, 0, KEY_READ, &key) != ERROR_SUCCESS) {
        return false;
    }
    DWORD type = 0;
    DWORD bytes = static_cast<DWORD>(cch * sizeof(wchar_t));
    const LONG st = RegQueryValueExW(key, value, nullptr, &type,
                                     reinterpret_cast<LPBYTE>(buf), &bytes);
    RegCloseKey(key);
    if (st != ERROR_SUCCESS || (type != REG_SZ && type != REG_EXPAND_SZ)) {
        buf[0] = 0;
        return false;
    }
    buf[cch - 1] = 0;
    return buf[0] != 0;
}

static OsInfo DetectOs() {
    OsInfo o;
    OSVERSIONINFOW vi{};
    if (Undoc::RtlGetVersion(&vi)) {
        o.major = vi.dwMajorVersion;
        o.minor = vi.dwMinorVersion;
        o.build = vi.dwBuildNumber;
        o.ok = true;
    } else {
        wchar_t majorStr[16] = {};
        wchar_t buildStr[16] = {};
        if (ReadRegSz(HKEY_LOCAL_MACHINE,
                      L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion",
                      L"CurrentMajorVersionNumber", majorStr, 16)) {
            o.major = static_cast<DWORD>(_wtol(majorStr));
        }
        if (ReadRegSz(HKEY_LOCAL_MACHINE,
                      L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion",
                      L"CurrentBuildNumber", buildStr, 16)) {
            o.build = static_cast<DWORD>(_wtol(buildStr));
            o.ok = o.build != 0;
        }
        if (o.major == 0 && o.build >= 22000) {
            o.major = 10;
        }
    }

    o.isWin11 = (o.major >= 10 && o.build >= 22000);

    DWORD dummy = 0;
    if (!GetProductInfo(o.major ? o.major : 10, o.minor, 0, 0, &o.productType)) {
        o.productType = 0;
    }
    (void)dummy;

    ReadRegSz(HKEY_LOCAL_MACHINE,
              L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion",
              L"DisplayVersion", o.displayVersion, 32);
    if (!o.displayVersion[0]) {
        ReadRegSz(HKEY_LOCAL_MACHINE,
                  L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion",
                  L"ReleaseId", o.displayVersion, 32);
    }
    ReadRegSz(HKEY_LOCAL_MACHINE,
              L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion",
              L"ProductName", o.productName, 64);

    const wchar_t* ed = EditionFromProduct(o.productType);
    if (ed && ed[0]) {
        CopyTrunc(o.edition, 64, ed);
    } else if (o.productName[0]) {
        // ProductName is often "Windows 10 Pro" even on Windows 11.
        CopyTrunc(o.edition, 64, o.productName);
    }

    if (o.major < 10) {
        Wh_Log(L"Warning: OS %u.%u.%u is older than Windows 10; running anyway",
               o.major, o.minor, o.build);
    } else {
        Wh_Log(L"OS %u.%u.%u (%s) product=0x%X win11=%d", o.major, o.minor,
               o.build, o.displayVersion, o.productType, o.isWin11 ? 1 : 0);
    }
    return o;
}

// ---------------------------------------------------------------------------
// Live system info
// ---------------------------------------------------------------------------

struct SysInfo {
    wchar_t userName[128] = {};
    wchar_t computerName[64] = {};
    wchar_t cpuName[128] = {};
    wchar_t gpuName[128] = {};
    wchar_t ramText[32] = {};
    wchar_t detectedEditionLine[96] = {};
    wchar_t editionLine[96] = {};
    wchar_t userPicture[MAX_PATH] = {};
    wchar_t manufacturer[64] = {};
    wchar_t oemLogo[MAX_PATH] = {};
};

static void QueryUserName(wchar_t* buf, size_t cch) {
    buf[0] = 0;
    using Fn = BOOLEAN(WINAPI*)(int, LPWSTR, PULONG);
    HMODULE secur32 = LoadLibraryW(L"secur32.dll");
    if (secur32) {
        const auto fn =
            reinterpret_cast<Fn>(GetProcAddress(secur32, "GetUserNameExW"));
        ULONG n = static_cast<ULONG>(cch);
        if (fn && fn(WC_NameDisplay, buf, &n) && buf[0]) {
            FreeLibrary(secur32);
            return;
        }
        buf[0] = 0;
        FreeLibrary(secur32);
    }
    DWORD n = static_cast<DWORD>(cch);
    if (!GetUserNameW(buf, &n)) {
        CopyTrunc(buf, cch, Ui(UiText::UserFallback));
    }
}

static void QueryComputerName(wchar_t* buf, size_t cch) {
    DWORD n = static_cast<DWORD>(cch);
    if (GetComputerNameExW(ComputerNamePhysicalDnsHostname, buf, &n) && buf[0]) {
        return;
    }
    n = static_cast<DWORD>(cch);
    if (!GetComputerNameW(buf, &n)) {
        CopyTrunc(buf, cch, Ui(UiText::ComputerFallback));
    }
}

static void QueryCpuName(wchar_t* buf, size_t cch) {
    if (!ReadRegSz(HKEY_LOCAL_MACHINE,
                   L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",
                   L"ProcessorNameString", buf, cch)) {
        SYSTEM_INFO si{};
        GetNativeSystemInfo(&si);
        swprintf_s(buf, cch, Ui(UiText::CoreProcessorFormat),
                   si.dwNumberOfProcessors);
        return;
    }
    TrimInPlace(buf);
}

static void QueryGpuName(wchar_t* buf, size_t cch) {
    buf[0] = 0;
    DISPLAY_DEVICEW dd{};
    dd.cb = sizeof(dd);
    for (DWORD i = 0; EnumDisplayDevicesW(nullptr, i, &dd, 0); ++i) {
        if (dd.StateFlags & DISPLAY_DEVICE_MIRRORING_DRIVER) {
            continue;
        }
        if (dd.StateFlags & DISPLAY_DEVICE_PRIMARY_DEVICE) {
            CopyTrunc(buf, cch, dd.DeviceString);
            TrimInPlace(buf);
            if (buf[0]) {
                return;
            }
        }
    }
    dd.cb = sizeof(dd);
    if (EnumDisplayDevicesW(nullptr, 0, &dd, 0)) {
        CopyTrunc(buf, cch, dd.DeviceString);
        TrimInPlace(buf);
    }
    if (!buf[0]) {
        CopyTrunc(buf, cch, Ui(UiText::DisplayAdapter));
    }
}

static void QueryRam(wchar_t* buf, size_t cch) {
    MEMORYSTATUSEX ms{};
    ms.dwLength = sizeof(ms);
    if (!GlobalMemoryStatusEx(&ms)) {
        CopyTrunc(buf, cch, Ui(UiText::RamUnknown));
        return;
    }
    const double gb = static_cast<double>(ms.ullTotalPhys) / (1024.0 * 1024.0 * 1024.0);
    swprintf_s(buf, cch, Ui(UiText::RamFormat), gb);
}

static bool FileExistsW(const wchar_t* path) {
    if (!path || !*path) {
        return false;
    }
    const DWORD a = GetFileAttributesW(path);
    return a != INVALID_FILE_ATTRIBUTES && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

static bool LooksLikeImage(const wchar_t* path) {
    const wchar_t* name = PathFindFileNameW(path);
    if (!name || !*name || name[0] == L'.' || EqualsIgnoreCase(name, L"desktop.ini")) {
        return false;
    }
    const wchar_t* ext = PathFindExtensionW(path);
    if (!ext || !*ext) {
        // Public\AccountPictures often stores JPEGs with no extension.
        return true;
    }
    return EqualsIgnoreCase(ext, L".png") || EqualsIgnoreCase(ext, L".jpg") ||
           EqualsIgnoreCase(ext, L".jpeg") || EqualsIgnoreCase(ext, L".bmp") ||
           EqualsIgnoreCase(ext, L".gif") || EqualsIgnoreCase(ext, L".jfif") ||
           EqualsIgnoreCase(ext, L".accountpicture-ms");
}

static bool NewestImageInFolder(const wchar_t* folder, wchar_t* out, size_t cch) {
    wchar_t pattern[MAX_PATH];
    if (swprintf_s(pattern, L"%s\\*.*", folder) < 0) {
        return false;
    }
    WIN32_FIND_DATAW fd{};
    HANDLE h = FindFirstFileW(pattern, &fd);
    if (h == INVALID_HANDLE_VALUE) {
        return false;
    }
    ULARGE_INTEGER best{};
    wchar_t bestPath[MAX_PATH] = {};
    do {
        if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) {
            continue;
        }
        wchar_t full[MAX_PATH];
        if (swprintf_s(full, L"%s\\%s", folder, fd.cFileName) < 0) {
            continue;
        }
        if (!LooksLikeImage(full)) {
            continue;
        }
        ULARGE_INTEGER sz;
        sz.LowPart = fd.nFileSizeLow;
        sz.HighPart = fd.nFileSizeHigh;
        if (sz.QuadPart >= best.QuadPart) {
            best = sz;
            CopyTrunc(bestPath, MAX_PATH, full);
        }
    } while (FindNextFileW(h, &fd));
    FindClose(h);
    if (!bestPath[0]) {
        return false;
    }
    CopyTrunc(out, cch, bestPath);
    return true;
}

static bool CurrentUserSidString(wchar_t* buf, size_t cch) {
    buf[0] = 0;
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &token)) {
        return false;
    }
    DWORD need = 0;
    GetTokenInformation(token, TokenUser, nullptr, 0, &need);
    if (need == 0) {
        CloseHandle(token);
        return false;
    }
    std::vector<BYTE> raw(need);
    bool ok = false;
    if (GetTokenInformation(token, TokenUser, raw.data(), need, &need)) {
        auto* tu = reinterpret_cast<TOKEN_USER*>(raw.data());
        LPWSTR sid = nullptr;
        if (tu && tu->User.Sid && ConvertSidToStringSidW(tu->User.Sid, &sid) &&
            sid) {
            CopyTrunc(buf, cch, sid);
            LocalFree(sid);
            ok = buf[0] != 0;
        }
    }
    CloseHandle(token);
    return ok;
}

static bool TryPicturePath(const wchar_t* path, wchar_t* buf, size_t cch) {
    if (!FileExistsW(path)) {
        return false;
    }
    CopyTrunc(buf, cch, path);
    return true;
}

static void QueryUserPicture(wchar_t* buf, size_t cch) {
    buf[0] = 0;

    wchar_t sid[128] = {};
    const bool haveSid = CurrentUserSidString(sid, 128);

    // Win10/11: HKLM...\AccountPicture\Users\{SID}\Image448 etc.
    if (haveSid) {
        wchar_t key[256];
        if (swprintf_s(key,
                       L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\"
                       L"AccountPicture\\Users\\%s",
                       sid) >= 0) {
            const wchar_t* vals[] = {L"Image448", L"Image240", L"Image192",
                                     L"Image96",  L"Image48",  L"Image32",
                                     L"Image"};
            for (const wchar_t* v : vals) {
                wchar_t path[MAX_PATH] = {};
                if (ReadRegSz(HKEY_LOCAL_MACHINE, key, v, path, MAX_PATH)) {
                    wchar_t expanded[MAX_PATH] = {};
                    if (ExpandEnvironmentStringsW(path, expanded, MAX_PATH) &&
                        TryPicturePath(expanded, buf, cch)) {
                        Wh_Log(L"Account picture (registry %s): %s", v, buf);
                        return;
                    }
                    if (TryPicturePath(path, buf, cch)) {
                        Wh_Log(L"Account picture (registry %s): %s", v, buf);
                        return;
                    }
                }
            }
        }

        wchar_t pub[MAX_PATH] = {};
        if (ExpandEnvironmentStringsW(L"%PUBLIC%\\AccountPictures", pub,
                                      MAX_PATH)) {
            wchar_t folder[MAX_PATH];
            if (swprintf_s(folder, L"%s\\%s", pub, sid) >= 0 &&
                NewestImageInFolder(folder, buf, cch)) {
                Wh_Log(L"Account picture (Public): %s", buf);
                return;
            }
        }
    }

    wchar_t local[MAX_PATH] = {};
    if (SUCCEEDED(SHGetFolderPathW(nullptr, CSIDL_LOCAL_APPDATA, nullptr,
                                   SHGFP_TYPE_CURRENT, local))) {
        wchar_t folder[MAX_PATH];
        if (swprintf_s(folder, L"%s\\Microsoft\\Windows\\AccountPicture",
                       local) >= 0) {
            const wchar_t* names[] = {L"UserImage.jpg", L"UserImage.png",
                                      L"UserImage.bmp"};
            for (const wchar_t* n : names) {
                wchar_t p[MAX_PATH];
                if (swprintf_s(p, L"%s\\%s", folder, n) >= 0 &&
                    TryPicturePath(p, buf, cch)) {
                    Wh_Log(L"Account picture (LocalAppData): %s", buf);
                    return;
                }
            }
            if (NewestImageInFolder(folder, buf, cch)) {
                Wh_Log(L"Account picture (LocalAppData folder): %s", buf);
                return;
            }
        }
    }

    PWSTR known = nullptr;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_AccountPictures, 0, nullptr,
                                       &known)) &&
        known) {
        NewestImageInFolder(known, buf, cch);
        CoTaskMemFree(known);
        if (buf[0]) {
            Wh_Log(L"Account picture (FOLDERID_AccountPictures): %s", buf);
            return;
        }
    }

    wchar_t roaming[MAX_PATH] = {};
    if (SUCCEEDED(SHGetFolderPathW(nullptr, CSIDL_APPDATA, nullptr,
                                   SHGFP_TYPE_CURRENT, roaming))) {
        wchar_t folder[MAX_PATH];
        if (swprintf_s(folder, L"%s\\Microsoft\\Windows\\AccountPictures",
                       roaming) >= 0) {
            if (NewestImageInFolder(folder, buf, cch)) {
                Wh_Log(L"Account picture (Roaming): %s", buf);
                return;
            }
        }
    }

    wchar_t shellPath[MAX_PATH] = {};
    if (Undoc::SHGetUserPicturePath(shellPath, MAX_PATH) &&
        TryPicturePath(shellPath, buf, cch)) {
        Wh_Log(L"Account picture (SHGetUserPicturePath): %s", buf);
        return;
    }

    wchar_t common[MAX_PATH] = {};
    if (SUCCEEDED(SHGetFolderPathW(nullptr, CSIDL_COMMON_APPDATA, nullptr,
                                   SHGFP_TYPE_CURRENT, common))) {
        const wchar_t* names[] = {L"user.png", L"user.bmp", L"guest.png",
                                  L"user-192.png", L"user-48.png", L"user-32.png"};
        for (const wchar_t* n : names) {
            wchar_t p[MAX_PATH];
            if (swprintf_s(p, L"%s\\Microsoft\\User Account Pictures\\%s",
                           common, n) < 0) {
                continue;
            }
            if (TryPicturePath(p, buf, cch)) {
                Wh_Log(L"Account picture (default ProgramData): %s", buf);
                return;
            }
        }
    }
    Wh_Log(L"Account picture not found; using silhouette");
}

static void QueryOemInfo(wchar_t* maker, size_t mcch, wchar_t* logo, size_t lcch) {
    maker[0] = 0;
    logo[0] = 0;
    ReadRegSz(HKEY_LOCAL_MACHINE,
              L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\OEMInformation",
              L"Manufacturer", maker, mcch);
    wchar_t raw[MAX_PATH] = {};
    if (ReadRegSz(HKEY_LOCAL_MACHINE,
                  L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\OEMInformation",
                  L"Logo", raw, MAX_PATH)) {
        wchar_t expanded[MAX_PATH] = {};
        if (ExpandEnvironmentStringsW(raw, expanded, MAX_PATH) &&
            FileExistsW(expanded)) {
            CopyTrunc(logo, lcch, expanded);
        } else if (FileExistsW(raw)) {
            CopyTrunc(logo, lcch, raw);
        }
    }
    if (!maker[0]) {
        ReadRegSz(HKEY_LOCAL_MACHINE,
                  L"HARDWARE\\DESCRIPTION\\System\\BIOS",
                  L"SystemManufacturer", maker, mcch);
    }
    if (maker[0]) {
        TrimInPlace(maker);
    }
    if (logo[0]) {
        Wh_Log(L"OEM logo: %s (%s)", logo, maker);
    } else if (maker[0]) {
        Wh_Log(L"OEM manufacturer (no logo): %s", maker);
    }
}

static SysInfo CollectSysInfo(const OsInfo& os) {
    SysInfo s;
    QueryUserName(s.userName, 128);
    QueryComputerName(s.computerName, 64);
    CharUpperBuffW(s.computerName, static_cast<DWORD>(wcslen(s.computerName)));
    QueryCpuName(s.cpuName, 128);
    QueryGpuName(s.gpuName, 128);
    QueryRam(s.ramText, 32);
    QueryUserPicture(s.userPicture, MAX_PATH);
    QueryOemInfo(s.manufacturer, 64, s.oemLogo, MAX_PATH);

    const wchar_t* family = os.isWin11 ? L"Windows 11" : L"Windows 10";
    if (os.major > 0 && os.major < 10) {
        family = L"Windows";
    }

    // Prefer a short "Windows 11 Pro" line. If edition already contains
    // "Windows", use it as-is (registry ProductName fallback).
    if (os.edition[0] && StartsWithIgnoreCase(os.edition, L"Windows")) {
        if (os.displayVersion[0]) {
            swprintf_s(s.editionLine, L"%s (%s)", os.edition, os.displayVersion);
        } else {
            CopyTrunc(s.editionLine, 96, os.edition);
        }
    } else if (os.edition[0]) {
        if (os.displayVersion[0]) {
            swprintf_s(s.editionLine, L"%s %s (%s)", family, os.edition,
                       os.displayVersion);
        } else {
            swprintf_s(s.editionLine, L"%s %s", family, os.edition);
        }
    } else if (os.displayVersion[0]) {
        swprintf_s(s.editionLine, L"%s (%s)", family, os.displayVersion);
    } else {
        CopyTrunc(s.editionLine, 96, family);
    }
    CopyTrunc(s.detectedEditionLine, ARRAYSIZE(s.detectedEditionLine),
              s.editionLine);
    return s;
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

struct OemLink {
    std::wstring title;
    std::wstring target;
    std::wstring description;
};

enum class VisualStyle : int {
    Vista = 0,
    Windows7 = 1,
};

enum class WindowsVersionText : int {
    Detected = 0,
    Windows10,
    Windows81,
    Windows8,
    Windows7Ultimate,
    Windows7Home,
    Windows7Starter,
    Windows7,
    WindowsVistaStarter,
    WindowsVistaUltimate,
    WindowsVistaHome,
    WindowsVista,
    WindowsXpHome,
    WindowsXpProfessional,
    WindowsXp,
    Windows98,
    Windows95,
};

struct Settings {
    VisualStyle visualStyle = VisualStyle::Vista;
    UiLanguage language = UiLanguage::Automatic;
    WindowsVersionText windowsVersionText = WindowsVersionText::Detected;
    bool showTrayIcon = true;
    bool runAtStartup = false;
    bool showOffers = true;
    bool allowOnlineOffers = false;
    bool preferClassicCpl = false;
    bool vistaItemNames = false;
    std::wstring hotkey = L"Ctrl+Alt+W";
    std::wstring oemSectionTitle = L"Offers from your computer manufacturer";
    std::wstring resourceFolder;
    std::vector<OemLink> oemLinks;
};

static void SplitOemEntry(const wchar_t* raw, OemLink* out) {
    out->title.clear();
    out->target.clear();
    out->description.clear();
    if (!raw || !*raw) {
        return;
    }
    std::wstring s(raw);
    const size_t p1 = s.find(L'|');
    if (p1 == std::wstring::npos) {
        out->title = s;
        return;
    }
    out->title = s.substr(0, p1);
    const size_t p2 = s.find(L'|', p1 + 1);
    if (p2 == std::wstring::npos) {
        out->target = s.substr(p1 + 1);
    } else {
        out->target = s.substr(p1 + 1, p2 - p1 - 1);
        out->description = s.substr(p2 + 1);
    }
}

struct WindowsVersionTextChoice {
    WindowsVersionText value;
    const wchar_t* key;
    const wchar_t* label;
};

static constexpr WindowsVersionTextChoice kWindowsVersionTextChoices[] = {
    {WindowsVersionText::Detected, L"detected", nullptr},
    {WindowsVersionText::Windows10, L"windows10", L"Windows 10"},
    {WindowsVersionText::Windows81, L"windows81", L"Windows 8.1"},
    {WindowsVersionText::Windows8, L"windows8", L"Windows 8"},
    {WindowsVersionText::Windows7Ultimate, L"windows7ultimate",
     L"Windows 7 Ultimate"},
    {WindowsVersionText::Windows7Home, L"windows7home", L"Windows 7 Home"},
    {WindowsVersionText::Windows7Starter, L"windows7starter",
     L"Windows 7 Starter"},
    {WindowsVersionText::Windows7, L"windows7", L"Windows 7"},
    {WindowsVersionText::WindowsVistaStarter, L"windowsvistastarter",
     L"Windows Vista Starter"},
    {WindowsVersionText::WindowsVistaUltimate, L"windowsvistaultimate",
     L"Windows Vista Ultimate"},
    {WindowsVersionText::WindowsVistaHome, L"windowsvistahome",
     L"Windows Vista Home"},
    {WindowsVersionText::WindowsVista, L"windowsvista", L"Windows Vista"},
    {WindowsVersionText::WindowsXpHome, L"windowsxphome", L"Windows XP Home"},
    {WindowsVersionText::WindowsXpProfessional, L"windowsxpprofessional",
     L"Windows XP Professional"},
    {WindowsVersionText::WindowsXp, L"windowsxp", L"Windows XP"},
    {WindowsVersionText::Windows98, L"windows98", L"Windows 98"},
    {WindowsVersionText::Windows95, L"windows95", L"Windows 95"},
};

static bool TryParseWindowsVersionText(const wchar_t* key,
                                       WindowsVersionText* value) noexcept {
    if (!key || !value) {
        return false;
    }
    for (const auto& choice : kWindowsVersionTextChoices) {
        if (EqualsIgnoreCase(key, choice.key)) {
            *value = choice.value;
            return true;
        }
    }
    return false;
}

static const wchar_t* WindowsVersionTextLabel(
    WindowsVersionText value) noexcept {
    for (const auto& choice : kWindowsVersionTextChoices) {
        if (choice.value == value) {
            return choice.label;
        }
    }
    return nullptr;
}

static constexpr wchar_t kRunAtStartupOverrideValue[] =
    L"runAtStartup.override.v2";
static constexpr wchar_t kRunAtStartupSnapshotValue[] =
    L"runAtStartup.settingSnapshot.v2";

static int WindhawkRunAtStartupSetting() {
    return Wh_GetIntSetting(L"runAtStartup") != 0 ? 1 : 0;
}

static void StoreRunAtStartupPreference(bool enabled) {
    const int value = enabled ? 1 : 0;
    const int settingSnapshot = WindhawkRunAtStartupSetting();
    const BOOL overrideStored =
        Wh_SetIntValue(kRunAtStartupOverrideValue, value);
    const BOOL snapshotStored =
        Wh_SetIntValue(kRunAtStartupSnapshotValue, settingSnapshot);
    if (!overrideStored || !snapshotStored) {
        Wh_Log(L"Failed to store the run-at-startup preference");
    }
}

static void SyncRunAtStartupFromWindhawk() {
    const int setting = WindhawkRunAtStartupSetting();
    const BOOL overrideStored =
        Wh_SetIntValue(kRunAtStartupOverrideValue, setting);
    const BOOL snapshotStored =
        Wh_SetIntValue(kRunAtStartupSnapshotValue, setting);
    if (!overrideStored || !snapshotStored) {
        Wh_Log(L"Failed to synchronize the Windhawk run-at-startup setting");
    }
}

static bool ResolveRunAtStartupPreference() {
    const int setting = WindhawkRunAtStartupSetting();
    const int overrideValue =
        Wh_GetIntValue(kRunAtStartupOverrideValue, -1);
    const int settingSnapshot =
        Wh_GetIntValue(kRunAtStartupSnapshotValue, -1);

    if ((overrideValue == 0 || overrideValue == 1) &&
        settingSnapshot == setting) {
        return overrideValue != 0;
    }

    // The Windhawk setting wins after an external settings change and during
    // migration from the old unsynchronized local-storage value. Recording a
    // snapshot lets the in-window checkbox persist without permanently
    // overriding a later Windhawk settings change.
    const BOOL overrideStored =
        Wh_SetIntValue(kRunAtStartupOverrideValue, setting);
    const BOOL snapshotStored =
        Wh_SetIntValue(kRunAtStartupSnapshotValue, setting);
    if (!overrideStored || !snapshotStored) {
        Wh_Log(L"Failed to initialize the run-at-startup preference");
    }
    return setting != 0;
}

static Settings LoadSettings() {
    Settings s;
    {
        WhString v(L"visualStyle");
        if (EqualsIgnoreCase(v.c_str(), L"windows7")) {
            s.visualStyle = VisualStyle::Windows7;
        }
    }
    {
        WhString v(L"language");
        if (!TryParseUiLanguage(v.c_str(), &s.language)) {
            Wh_Log(L"Unknown interface language setting '%s'; following the "
                   L"Windows display language",
                   v.c_str());
            s.language = UiLanguage::Automatic;
        }
        s.language = ResolveUiLanguage(s.language);
    }
    {
        WhString v(L"windowsVersionText");
        if (!TryParseWindowsVersionText(v.c_str(), &s.windowsVersionText)) {
            Wh_Log(L"Unknown Windows-version text setting '%s'; using detected "
                   L"system version",
                   v.c_str());
            s.windowsVersionText = WindowsVersionText::Detected;
        }
    }
    s.showTrayIcon = Wh_GetIntSetting(L"showTrayIcon") != 0;
    s.showOffers = Wh_GetIntSetting(L"showOffers") != 0;
    s.allowOnlineOffers = Wh_GetIntSetting(L"allowOnlineOffers") != 0;
    s.preferClassicCpl = Wh_GetIntSetting(L"preferClassicCpl") != 0;
    s.vistaItemNames = Wh_GetIntSetting(L"vistaItemNames") != 0;

    s.runAtStartup = ResolveRunAtStartupPreference();

    {
        WhString v(L"hotkey");
        s.hotkey = v.c_str();
    }
    {
        WhString v(L"oemSectionTitle");
        if (!v.empty()) {
            s.oemSectionTitle = v.c_str();
        }
    }
    {
        WhString v(L"resourceFolder");
        s.resourceFolder = v.c_str();
    }

    s.oemLinks.clear();
    for (int i = 0; i < kMaxOemLinks; ++i) {
        WhString entry(L"oemLinks[%d]", i);
        if (entry.empty()) {
            // Windhawk returns "" for missing indices; stop at the first hole
            // after we have started, but also allow a leading empty default.
            if (i == 0) {
                continue;
            }
            break;
        }
        OemLink link;
        SplitOemEntry(entry.c_str(), &link);
        if (link.title.empty() && link.target.empty()) {
            continue;
        }
        if (link.title.empty()) {
            link.title = link.target;
        }
        s.oemLinks.push_back(std::move(link));
    }
    return s;
}

static void ApplyWindowsVersionText(SysInfo* sys,
                                    WindowsVersionText value) noexcept {
    if (!sys) {
        return;
    }
    const wchar_t* label = WindowsVersionTextLabel(value);
    if (label) {
        CopyTrunc(sys->editionLine, ARRAYSIZE(sys->editionLine), label);
    } else if (sys->detectedEditionLine[0]) {
        CopyTrunc(sys->editionLine, ARRAYSIZE(sys->editionLine),
                  sys->detectedEditionLine);
    }
}

// ---------------------------------------------------------------------------
// Launch helpers (allow-listed)
// ---------------------------------------------------------------------------

static const wchar_t* UiProductName();

static bool LaunchShell(HWND owner, const wchar_t* file, const wchar_t* params) {
    if (!file || !*file) {
        return false;
    }
    SHELLEXECUTEINFOW sei{};
    sei.cbSize = sizeof(sei);
    sei.fMask = SEE_MASK_FLAG_NO_UI;
    sei.hwnd = owner;
    sei.lpVerb = L"open";
    sei.lpFile = file;
    sei.lpParameters = (params && *params) ? params : nullptr;
    sei.nShow = SW_SHOWNORMAL;
    if (!ShellExecuteExW(&sei)) {
        Wh_Log(L"ShellExecuteEx failed (%u): %s %s", GetLastError(), file,
               params ? params : L"");
        return false;
    }
    return true;
}

static bool HasPathMeta(const wchar_t* s) {
    return s && (wcschr(s, L'&') || wcschr(s, L'|') || wcschr(s, L'>') ||
                 wcschr(s, L'<') || wcschr(s, L'^') || wcsstr(s, L".."));
}

static bool IsLocalProtocol(const wchar_t* t) {
    return StartsWithIgnoreCase(t, L"ms-settings:") ||
           StartsWithIgnoreCase(t, L"ms-windows-store:") ||
           StartsWithIgnoreCase(t, L"ms-contact-support:") ||
           StartsWithIgnoreCase(t, L"windowsdefender:") ||
           StartsWithIgnoreCase(t, L"feedback-hub:") ||
           StartsWithIgnoreCase(t, L"ms-get-started:") ||
           StartsWithIgnoreCase(t, L"shell:");
}

static bool IsHttp(const wchar_t* t) {
    return StartsWithIgnoreCase(t, L"https://") ||
           StartsWithIgnoreCase(t, L"http://");
}

static bool IsDangerousFileName(const wchar_t* name) {
    return EqualsIgnoreCase(name, L"cmd.exe") ||
           EqualsIgnoreCase(name, L"command.com") ||
           EqualsIgnoreCase(name, L"powershell.exe") ||
           EqualsIgnoreCase(name, L"powershell_ise.exe") ||
           EqualsIgnoreCase(name, L"pwsh.exe") ||
           EqualsIgnoreCase(name, L"wscript.exe") ||
           EqualsIgnoreCase(name, L"cscript.exe") ||
           EqualsIgnoreCase(name, L"mshta.exe") ||
           EqualsIgnoreCase(name, L"rundll32.exe") ||
           EqualsIgnoreCase(name, L"regsvr32.exe") ||
           EqualsIgnoreCase(name, L"reg.exe") ||
           EqualsIgnoreCase(name, L"msiexec.exe") ||
           EqualsIgnoreCase(name, L"bitsadmin.exe") ||
           EqualsIgnoreCase(name, L"certutil.exe") ||
           EqualsIgnoreCase(name, L"msdt.exe") ||
           EqualsIgnoreCase(name, L"forfiles.exe") ||
           EqualsIgnoreCase(name, L"wmic.exe") ||
           EqualsIgnoreCase(name, L"bash.exe") ||
           EqualsIgnoreCase(name, L"wt.exe");
}

// User-supplied OEM target. Strict allow-list. No elevation, no script hosts.
static bool LaunchUserTarget(HWND owner, const wchar_t* target, bool allowOnline) {
    if (!target || !*target || HasPathMeta(target)) {
        return false;
    }
    if (IsLocalProtocol(target)) {
        return LaunchShell(owner, target, nullptr);
    }
    if (IsHttp(target)) {
        if (!allowOnline) {
            UiMessageBox(owner, Ui(UiText::OnlineDisabledBody),
                         UiProductName(), MB_OK | MB_ICONINFORMATION);
            return false;
        }
        if (!StartsWithIgnoreCase(target, L"https://") &&
            !StartsWithIgnoreCase(target, L"http://localhost") &&
            !StartsWithIgnoreCase(target, L"http://127.0.0.1")) {
            // Plain http to the public internet is refused even when online
            // offers are on (mixed-content / downgrade).
            UiMessageBox(owner, Ui(UiText::HttpsOnly), UiProductName(),
                         MB_OK | MB_ICONWARNING);
            return false;
        }
        return LaunchShell(owner, target, nullptr);
    }

    // Local file. Must exist. No arguments (prevents /c and similar).
    wchar_t expanded[MAX_PATH] = {};
    if (!ExpandEnvironmentStringsW(target, expanded, MAX_PATH)) {
        return false;
    }
    if (wcschr(expanded, L'"') || wcschr(expanded, L' ')) {
        // Quoted paths with args are rejected; a path that merely contains
        // spaces is OK if it is a single existing file.
    }
    if (wcschr(expanded, L'/') ) {
        // Treat a slash as an argument separator for safety.
        if (wcsstr(expanded, L" /")) {
            return false;
        }
    }

    const DWORD attr = GetFileAttributesW(expanded);
    if (attr == INVALID_FILE_ATTRIBUTES || (attr & FILE_ATTRIBUTE_DIRECTORY)) {
        Wh_Log(L"OEM target not a file: %s", expanded);
        return false;
    }
    const wchar_t* ext = PathFindExtensionW(expanded);
    if (!EqualsIgnoreCase(ext, L".exe") && !EqualsIgnoreCase(ext, L".cpl") &&
        !EqualsIgnoreCase(ext, L".msc") && !EqualsIgnoreCase(ext, L".lnk")) {
        return false;
    }
    if (IsDangerousFileName(PathFindFileNameW(expanded))) {
        Wh_Log(L"Rejected dangerous OEM target: %s", expanded);
        return false;
    }
    return LaunchShell(owner, expanded, nullptr);
}

static bool LaunchDefaultBrowser(HWND owner) {
    wchar_t browser[MAX_PATH] = {};
    DWORD cch = MAX_PATH;
    if (SUCCEEDED(AssocQueryStringW(ASSOCF_IS_PROTOCOL, ASSOCSTR_EXECUTABLE,
                                    L"http", L"open", browser, &cch)) &&
        browser[0]) {
        const wchar_t* name = PathFindFileNameW(browser);
        if (name && !IsDangerousFileName(name)) {
            if (LaunchShell(owner, browser, nullptr)) {
                return true;
            }
        }
    }
    // Fallback: let the shell pick the http handler.
    return LaunchShell(owner, L"https://www.microsoft.com/", nullptr);
}

static constexpr wchar_t kInternalMediaPlayerLegacy[] =
    L"internal:windows-media-player-legacy";

static bool TryMediaPlayerPath(const wchar_t* raw, wchar_t* out, size_t cch) {
    if (!raw || !*raw || !out || cch == 0) {
        return false;
    }
    wchar_t path[MAX_PATH] = {};
    const DWORD expanded = ExpandEnvironmentStringsW(raw, path, MAX_PATH);
    if (expanded == 0 || expanded >= MAX_PATH) {
        return false;
    }
    TrimInPlace(path);
    size_t len = wcslen(path);
    if (len >= 2 && path[0] == L'"' && path[len - 1] == L'"') {
        path[len - 1] = 0;
        memmove(path, path + 1, len * sizeof(wchar_t));
        TrimInPlace(path);
    }
    if (!FileExistsW(path) ||
        !EqualsIgnoreCase(PathFindFileNameW(path), L"wmplayer.exe")) {
        return false;
    }
    CopyTrunc(out, cch, path);
    return out[0] != 0;
}

// Resolve an absolute, existing path instead of starting a bare executable
// name. This avoids current-directory/PATH executable-search ambiguity.
static bool ResolveMediaPlayerLegacyPath(wchar_t* out, size_t cch) {
    if (!out || cch == 0) {
        return false;
    }
    out[0] = 0;

    PWSTR programFiles = nullptr;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_ProgramFiles, 0, nullptr,
                                       &programFiles)) &&
        programFiles) {
        wchar_t candidate[MAX_PATH] = {};
        if (swprintf_s(candidate, L"%s\\Windows Media Player\\wmplayer.exe",
                       programFiles) >= 0 &&
            TryMediaPlayerPath(candidate, out, cch)) {
            CoTaskMemFree(programFiles);
            return true;
        }
        CoTaskMemFree(programFiles);
    }

    const wchar_t* environmentCandidates[] = {
        L"%ProgramW6432%\\Windows Media Player\\wmplayer.exe",
        L"%ProgramFiles%\\Windows Media Player\\wmplayer.exe",
        L"%ProgramFiles(x86)%\\Windows Media Player\\wmplayer.exe",
    };
    for (const wchar_t* candidate : environmentCandidates) {
        if (TryMediaPlayerPath(candidate, out, cch)) {
            return true;
        }
    }

    wchar_t registered[MAX_PATH] = {};
    if (ReadRegSz(HKEY_LOCAL_MACHINE,
                  L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\"
                  L"wmplayer.exe",
                  nullptr, registered, MAX_PATH) &&
        TryMediaPlayerPath(registered, out, cch)) {
        return true;
    }
    return false;
}

static bool LaunchMediaPlayerLegacy(HWND owner) {
    wchar_t path[MAX_PATH] = {};
    if (ResolveMediaPlayerLegacyPath(path, MAX_PATH) &&
        LaunchShell(owner, path, nullptr)) {
        return true;
    }

    Wh_Log(L"Windows Media Player Legacy is unavailable");
    wchar_t prompt[768] = {};
    swprintf_s(prompt, L"%s\n\n%s", Ui(UiText::MediaPlayerMissing),
               Ui(UiText::OpenOptionalFeatures));
    const int answer = UiMessageBox(
        owner, prompt, UiProductName(),
        MB_YESNO | MB_ICONINFORMATION | MB_DEFBUTTON1);
    if (answer == IDYES) {
        return LaunchShell(owner, L"ms-settings:optionalfeatures", nullptr);
    }
    return false;
}

static bool LaunchTask(HWND owner, const wchar_t* settingsUri,
                       const wchar_t* classicFile, const wchar_t* classicParams,
                       bool preferClassic) {
    if (settingsUri && EqualsIgnoreCase(settingsUri, L"internal:default-browser")) {
        return LaunchDefaultBrowser(owner);
    }
    if (settingsUri && EqualsIgnoreCase(settingsUri, kInternalMediaPlayerLegacy)) {
        return LaunchMediaPlayerLegacy(owner);
    }
    if (preferClassic && classicFile && *classicFile) {
        if (LaunchShell(owner, classicFile, classicParams)) {
            return true;
        }
    }
    if (settingsUri && *settingsUri) {
        if (LaunchShell(owner, settingsUri, nullptr)) {
            return true;
        }
    }
    if (!preferClassic && classicFile && *classicFile) {
        return LaunchShell(owner, classicFile, classicParams);
    }
    return false;
}

