[[clang::no_destroy]] static std::optional<App> g_app;
#define g (*g_app)

static HANDLE g_stopEvent = nullptr;

static HICON GetAppHicon();

static bool IsWindows7Style() {
    return g.settings.visualStyle == VisualStyle::Windows7;
}

static const wchar_t* UiProductName() {
    return IsWindows7Style() ? Ui(UiText::GettingStarted)
                             : Ui(UiText::WelcomeCenter);
}

static const wchar_t* UiAboutTitle() {
    return IsWindows7Style() ? Ui(UiText::AboutGetting)
                             : Ui(UiText::AboutWelcome);
}

static bool BuildAboutText(wchar_t* text, size_t cch) {
    if (!text || cch == 0) {
        return false;
    }
    text[0] = 0;
    const CreditText& credit = LocalizedCreditText();
    return swprintf_s(
               text, cch,
               L"%s\n%s %s\n\n%s\n%s\n\n%s: MIT\n%s: %s\n\n%s: %s\n%s",
               UiProductName(), kModDisplayName, kModVersion,
               Ui(UiText::FaithfulRecreation), Ui(UiText::NoSystemFiles),
               Ui(UiText::License), Ui(UiText::Author), kModAuthor,
               credit.heading, kCreditContributor, credit.thanks) >= 0;
}

static void ShowAboutDialog(HWND requestedOwner) {
    // The main window normally stays alive while hidden. A message box owned by
    // that hidden (or minimized) window can appear behind other windows or seem
    // not to open at all. Use it only when it is a usable visible owner;
    // otherwise show a foreground, unowned dialog from this UI thread.
    HWND owner = requestedOwner;
    if (!owner || !IsWindow(owner) || !IsWindowVisible(owner) ||
        IsIconic(owner)) {
        owner = nullptr;
    }

    wchar_t aboutText[1024] = {};
    if (!BuildAboutText(aboutText, ARRAYSIZE(aboutText))) {
        CopyTrunc(aboutText, ARRAYSIZE(aboutText), kModDisplayName);
    }
    if (owner) {
        SetForegroundWindow(owner);
    }
    UiMessageBox(owner, aboutText, UiAboutTitle(),
                 MB_OK | MB_ICONINFORMATION | MB_SETFOREGROUND);
}

// The UI runs inside explorer.exe, so its process-level AppUserModelID belongs
// to File Explorer. Assign only this top-level window a documented, explicit
// identity; never change Explorer's process-wide identity.
static bool ApplyTaskbarIdentity(HWND hwnd) {
    if (!hwnd || !IsWindow(hwnd)) {
        return false;
    }

    IPropertyStore* rawStore = nullptr;
    HRESULT hr = SHGetPropertyStoreForWindow(
        hwnd, IID_IPropertyStore, reinterpret_cast<void**>(&rawStore));
    UniqueCom<IPropertyStore> store(rawStore);
    if (FAILED(hr) || !store) {
        Wh_Log(L"SHGetPropertyStoreForWindow failed: 0x%08X", hr);
        return false;
    }

    PROPVARIANT value{};
    hr = InitPropVariantFromString(kTaskbarAppId, &value);
    if (FAILED(hr)) {
        Wh_Log(L"Init taskbar AppUserModelID failed: 0x%08X", hr);
        return false;
    }
    hr = store.get()->SetValue(PKEY_AppUserModel_ID, value);
    PropVariantClear(&value);
    if (FAILED(hr)) {
        Wh_Log(L"Set taskbar AppUserModelID failed: 0x%08X", hr);
        return false;
    }
    return true;
}

static void SetMenuDirection(HMENU menu, bool menuBar = false) {
    if (!menu) {
        return;
    }
    const int count = GetMenuItemCount(menu);
    for (int position = 0; position < count; ++position) {
        MENUITEMINFOW info{};
        info.cbSize = sizeof(info);
        info.fMask = MIIM_FTYPE;
        if (!GetMenuItemInfoW(menu, static_cast<UINT>(position), TRUE,
                              &info)) {
            continue;
        }
        info.fType &= ~(MFT_RIGHTORDER | MFT_RIGHTJUSTIFY);
        if (IsRtlLanguage()) {
            info.fType |= MFT_RIGHTORDER;
            if (menuBar && position == 0) {
                info.fType |= MFT_RIGHTJUSTIFY;
            }
        }
        SetMenuItemInfoW(menu, static_cast<UINT>(position), TRUE, &info);
    }
}

static void RefreshMenuLabels(HMENU bar) {
    if (!bar) {
        return;
    }
    HMENU file = GetSubMenu(bar, 0);
    HMENU view = GetSubMenu(bar, 1);
    HMENU help = GetSubMenu(bar, 2);
    if (file) {
        ModifyMenuW(file, 4002, MF_BYCOMMAND | MF_STRING, 4002,
                    Ui(UiText::MenuRefresh));
        ModifyMenuW(file, 4001, MF_BYCOMMAND | MF_STRING, 4001,
                    Ui(UiText::MenuClose));
        ModifyMenuW(bar, 0, MF_BYPOSITION | MF_POPUP,
                    reinterpret_cast<UINT_PTR>(file), Ui(UiText::MenuFile));
    }
    if (view) {
        ModifyMenuW(view, 4003, MF_BYCOMMAND | MF_STRING, 4003,
                    Ui(UiText::MenuShowAll));
        ModifyMenuW(view, 4002, MF_BYCOMMAND | MF_STRING, 4002,
                    Ui(UiText::MenuRefreshInfo));
        ModifyMenuW(view, 4005, MF_BYCOMMAND | MF_STRING, 4005,
                    Ui(UiText::MenuFullScreen));
        ModifyMenuW(bar, 1, MF_BYPOSITION | MF_POPUP,
                    reinterpret_cast<UINT_PTR>(view), Ui(UiText::MenuView));
    }
    if (help) {
        ModifyMenuW(help, 4004, MF_BYCOMMAND | MF_STRING, 4004,
                    Ui(IsWindows7Style() ? UiText::AboutGetting
                                         : UiText::AboutWelcome));
        ModifyMenuW(bar, 2, MF_BYPOSITION | MF_POPUP,
                    reinterpret_cast<UINT_PTR>(help), Ui(UiText::MenuHelp));
    }
    SetMenuDirection(file);
    SetMenuDirection(view);
    SetMenuDirection(help);
    SetMenuDirection(bar, true);
}

static void ApplyWindowDirection() {
    const bool rtl = IsRtlLanguage();
    if (g.main && IsWindow(g.main)) {
        LONG_PTR ex = GetWindowLongPtrW(g.main, GWL_EXSTYLE);
        ex = rtl ? (ex | WS_EX_RTLREADING) : (ex & ~WS_EX_RTLREADING);
        SetWindowLongPtrW(g.main, GWL_EXSTYLE, ex);
        if (g.fullScreen) {
            g.savedExStyle = rtl ? (g.savedExStyle | WS_EX_RTLREADING)
                                 : (g.savedExStyle & ~WS_EX_RTLREADING);
        }
        SetWindowPos(g.main, nullptr, 0, 0, 0, 0,
                     SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER |
                         SWP_NOACTIVATE | SWP_FRAMECHANGED);
    }
    if (g.checkbox && IsWindow(g.checkbox)) {
        LONG_PTR ex = GetWindowLongPtrW(g.checkbox, GWL_EXSTYLE);
        const LONG_PTR bits = WS_EX_RTLREADING;
        ex = rtl ? (ex | bits) : (ex & ~bits);
        SetWindowLongPtrW(g.checkbox, GWL_EXSTYLE, ex);
        LONG_PTR style = GetWindowLongPtrW(g.checkbox, GWL_STYLE);
        const LONG_PTR directionBits = BS_RIGHT | BS_RIGHTBUTTON;
        style = rtl ? (style | directionBits) : (style & ~directionBits);
        SetWindowLongPtrW(g.checkbox, GWL_STYLE, style);
        SetWindowPos(g.checkbox, nullptr, 0, 0, 0, 0,
                     SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER |
                         SWP_NOACTIVATE | SWP_FRAMECHANGED);
    }
}

static void RefreshSkinLabels() {
    ApplyWindowDirection();
    if (g.main && IsWindow(g.main)) {
        SetWindowTextW(g.main, UiProductName());
        if (HICON icon = GetAppHicon()) {
            SendMessageW(g.main, WM_SETICON, ICON_BIG,
                         reinterpret_cast<LPARAM>(icon));
            SendMessageW(g.main, WM_SETICON, ICON_SMALL,
                         reinterpret_cast<LPARAM>(icon));
            SetClassLongPtrW(g.main, GCLP_HICON,
                             reinterpret_cast<LONG_PTR>(icon));
            SetClassLongPtrW(g.main, GCLP_HICONSM,
                             reinterpret_cast<LONG_PTR>(icon));
        }
    }
    if (g.checkbox && IsWindow(g.checkbox)) {
        const wchar_t* text =
            Ui(IsWindows7Style() ? UiText::RunStartupGetting
                                 : UiText::RunStartupWelcome);
        SetWindowTextW(g.checkbox, text);
    }
    HMENU bar = nullptr;
    if (g.main && IsWindow(g.main)) {
        bar = GetMenu(g.main);
    }
    if (!bar) {
        bar = g.mainMenu;
    }
    if (bar) {
        RefreshMenuLabels(bar);
        if (g.main && IsWindow(g.main)) {
            DrawMenuBar(g.main);
        }
    }
}

static void RefreshSysInfo() {
    delete g.userPicBmp;
    g.userPicBmp = nullptr;
    delete g.oemLogoBmp;
    g.oemLogoBmp = nullptr;
    g.sys = CollectSysInfo(g.os);
    ApplyWindowsVersionText(&g.sys, g.settings.windowsVersionText);
}

// ---------------------------------------------------------------------------
// Icons
// ---------------------------------------------------------------------------

static void ClearIconCache() {
    for (auto& c : g.iconCache) {
        if (c.icon) {
            DestroyIcon(c.icon);
            c.icon = nullptr;
        }
        delete c.bmp;
        c.bmp = nullptr;
    }
    g.iconCache.clear();
}

// Idempotent. Must run while GDI+ is still alive (before GdiplusShutdown).
static void ReleaseUiResources() {
    g.uiFont.reset();
    g.uiFontBold.reset();
    g.checkFont.reset();
    g.buffer.release();
    ClearIconCache();

    auto dropBmp = [](Gdiplus::Bitmap*& p) {
        delete p;
        p = nullptr;
    };
    dropBmp(g.userPicBmp);
    dropBmp(g.userFrameBmp);
    dropBmp(g.oemLogoBmp);
    dropBmp(g.chevronBmp);
    dropBmp(g.greenArrowBmp);
    dropBmp(g.auroraBmp);
    if (g.segoeFamily) {
        delete g.segoeFamily;
        g.segoeFamily = nullptr;
    }
    dropBmp(g.pcBitmap);
    dropBmp(g.storeBitmap);
    dropBmp(g.mediaPlayerIconBmp);

    if (g.appIcon) {
        DestroyIcon(g.appIcon);
        g.appIcon = nullptr;
    }
    if (g.mediaPlayerIcon) {
        DestroyIcon(g.mediaPlayerIcon);
        g.mediaPlayerIcon = nullptr;
    }
    g.mediaPlayerIconAttempted = false;
    for (auto& e : g.embedBitmaps) {
        delete e.second;
        e.second = nullptr;
    }
    g.embedBitmaps.clear();
}

static HICON ExtractSizedIcon(SHSTOCKICONID id, UINT px) {
    SHSTOCKICONINFO loc{};
    loc.cbSize = sizeof(loc);
    if (SUCCEEDED(SHGetStockIconInfo(id, SHGSI_ICONLOCATION, &loc)) &&
        loc.szPath[0]) {
        HICON large = nullptr;
        if (SHDefExtractIconW(loc.szPath, loc.iIcon, 0, &large, nullptr, px) ==
                S_OK &&
            large) {
            return large;
        }
    }
    SHSTOCKICONINFO sii{};
    sii.cbSize = sizeof(sii);
    if (SUCCEEDED(SHGetStockIconInfo(id, SHGSI_ICON | SHGSI_LARGEICON, &sii)) &&
        sii.hIcon) {
        return sii.hIcon;
    }
    return nullptr;
}

static HICON LoadStockIcon(SHSTOCKICONID id) {
    for (const auto& c : g.iconCache) {
        if (c.id == id && c.icon) {
            return c.icon;
        }
    }
    HICON icon = ExtractSizedIcon(id, 256);
    if (!icon) {
        icon = ExtractSizedIcon(id, 48);
    }
    App::CachedIcon c;
    c.id = id;
    c.icon = icon;
    g.iconCache.push_back(c);
    return icon;
}

// Convert HICON to ARGB without the black halo Bitmap::FromHICON leaves.
// Draws the icon on black and white, recovers alpha, then drops leftover
// dark translucent fringe (the system-icon drop shadow).
static Gdiplus::Bitmap* BitmapFromIconNoHalo(HICON icon, int px) {
    if (!icon || px <= 0) {
        return nullptr;
    }

    BITMAPINFO bi{};
    bi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bi.bmiHeader.biWidth = px;
    bi.bmiHeader.biHeight = -px;
    bi.bmiHeader.biPlanes = 1;
    bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;

    HDC screen = GetDC(nullptr);
    if (!screen) {
        return nullptr;
    }
    void* bitsB = nullptr;
    void* bitsW = nullptr;
    UniqueGdi dibB(CreateDIBSection(screen, &bi, DIB_RGB_COLORS, &bitsB, nullptr, 0));
    UniqueGdi dibW(CreateDIBSection(screen, &bi, DIB_RGB_COLORS, &bitsW, nullptr, 0));
    UniqueDc dc(CreateCompatibleDC(screen));
    ReleaseDC(nullptr, screen);
    if (!dibB || !dibW || !bitsB || !bitsW || !dc) {
        return nullptr;
    }

    const int strideSrc = px * 4;
    HGDIOBJ old = SelectObject(dc.get(), dibB.get());
    memset(bitsB, 0x00, static_cast<size_t>(px) * strideSrc);
    DrawIconEx(dc.get(), 0, 0, icon, px, px, 0, nullptr, DI_NORMAL);
    SelectObject(dc.get(), dibW.get());
    memset(bitsW, 0xFF, static_cast<size_t>(px) * strideSrc);
    DrawIconEx(dc.get(), 0, 0, icon, px, px, 0, nullptr, DI_NORMAL);
    SelectObject(dc.get(), old);

    UniqueBitmap bmp;
    try {
        bmp.reset(new Gdiplus::Bitmap(px, px, PixelFormat32bppARGB));
    } catch (...) {
        Wh_Log(L"BitmapFromIconNoHalo: GDI+ Bitmap alloc threw");
        return nullptr;
    }
    if (!bmp.get() || bmp.get()->GetLastStatus() != Gdiplus::Ok) {
        return nullptr;
    }
    Gdiplus::BitmapData data{};
    const Gdiplus::Rect lockRc(0, 0, px, px);
    if (bmp.get()->LockBits(&lockRc, Gdiplus::ImageLockModeWrite,
                            PixelFormat32bppARGB, &data) != Gdiplus::Ok) {
        return nullptr;
    }

    auto* dst = static_cast<BYTE*>(data.Scan0);
    const auto* blk = static_cast<const BYTE*>(bitsB);
    const auto* wht = static_cast<const BYTE*>(bitsW);
    for (int y = 0; y < px; ++y) {
        BYTE* drow = dst + y * data.Stride;
        const BYTE* brow = blk + y * strideSrc;
        const BYTE* wrow = wht + y * strideSrc;
        for (int x = 0; x < px; ++x) {
            const int i = x * 4;
            const int bb = brow[i + 0], bg_ = brow[i + 1], br = brow[i + 2];
            const int wb = wrow[i + 0], wg = wrow[i + 1], wr = wrow[i + 2];
            int a = (255 - (wb - bb) + 255 - (wg - bg_) + 255 - (wr - br)) / 3;
            if (a < 0) {
                a = 0;
            }
            if (a > 255) {
                a = 255;
            }
            int r = br, gch = bg_, b = bb;
            if (a > 0 && a < 255) {
                r = IMin(255, br * 255 / a);
                gch = IMin(255, bg_ * 255 / a);
                b = IMin(255, bb * 255 / a);
            }
            const int lum = (r * 5 + gch * 6 + b * 5) / 16;
            const int sat = IMax(r, IMax(gch, b)) - IMin(r, IMin(gch, b));
            // Soft black/gray drop-shadow baked into many shell icons.
            if (sat < 22 && lum < 42 && a < 210) {
                a = 0;
            }
            if (a < 12) {
                a = r = gch = b = 0;
            }
            drow[i + 0] = static_cast<BYTE>(b);
            drow[i + 1] = static_cast<BYTE>(gch);
            drow[i + 2] = static_cast<BYTE>(r);
            drow[i + 3] = static_cast<BYTE>(a);
        }
    }
    bmp.get()->UnlockBits(&data);
    return bmp.release();
}

static Gdiplus::Bitmap* GetStockIconBitmap(SHSTOCKICONID id) {
    for (auto& c : g.iconCache) {
        if (c.id == id) {
            if (!c.bmp && c.icon) {
                c.bmp = BitmapFromIconNoHalo(c.icon, 256);
            }
            return c.bmp;
        }
    }
    HICON icon = ExtractSizedIcon(id, 256);
    if (!icon) {
        icon = ExtractSizedIcon(id, 48);
    }
    if (!icon) {
        return nullptr;
    }
    App::CachedIcon c;
    c.id = id;
    c.icon = icon;
    c.bmp = BitmapFromIconNoHalo(icon, 256);
    g.iconCache.push_back(c);
    return c.bmp;
}

static void DrawStockIconG(Gdiplus::Graphics& gr, SHSTOCKICONID id,
                           const RECT& rc) {
    using namespace Gdiplus;
    Bitmap* bmp = GetStockIconBitmap(id);
    if (!bmp) {
        return;
    }
    const int size = IMin(rc.right - rc.left, rc.bottom - rc.top);
    gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    gr.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    gr.DrawImage(bmp, rc.left, rc.top, size, size);
}

static Gdiplus::Bitmap* GetMediaPlayerIconBitmap() {
    if (g.mediaPlayerIconAttempted) {
        return g.mediaPlayerIconBmp;
    }
    g.mediaPlayerIconAttempted = true;

    wchar_t path[MAX_PATH] = {};
    if (!ResolveMediaPlayerLegacyPath(path, MAX_PATH)) {
        Wh_Log(L"Windows Media Player Legacy icon source was not found");
        return nullptr;
    }

    HICON icon = nullptr;
    const HRESULT extractHr =
        SHDefExtractIconW(path, 0, 0, &icon, nullptr, 256);
    if ((FAILED(extractHr) || !icon)) {
        SHFILEINFOW sfi{};
        if (SHGetFileInfoW(path, 0, &sfi, sizeof(sfi),
                           SHGFI_ICON | SHGFI_LARGEICON) &&
            sfi.hIcon) {
            icon = sfi.hIcon;
        }
    }
    if (!icon) {
        Wh_Log(L"Failed to extract Windows Media Player Legacy icon: %s", path);
        return nullptr;
    }

    g.mediaPlayerIcon = icon;
    g.mediaPlayerIconBmp = BitmapFromIconNoHalo(icon, 256);
    if (!g.mediaPlayerIconBmp) {
        Wh_Log(L"Failed to convert Windows Media Player Legacy icon");
    }
    return g.mediaPlayerIconBmp;
}

// ---------------------------------------------------------------------------
// Build item lists
// ---------------------------------------------------------------------------

static Item FromDef(const TaskDef& d, TaskTextId textId, bool vistaNames) {
    Item it;
    const TaskText& text = LocalizedTaskText(textId);
    it.title = vistaNames ? text.vistaTitle : text.title;
    it.description = text.description;
    it.settingsUri = textId == TaskTextId::Support
                         ? LocalizedSupportUrl()
                         : (d.settingsUri ? d.settingsUri : L"");
    it.classicFile = d.classicFile ? d.classicFile : L"";
    it.classicParams = d.classicParams ? d.classicParams : L"";
    it.icon = d.icon;
    it.embedPng = d.embedPng;
    if (g_activeLanguage == UiLanguage::English) {
        it.detailTitle = d.detailTitle ? d.detailTitle : it.title;
        it.detailBody = d.detailBody ? d.detailBody : it.description;
        it.actionLabel = d.actionLabel ? d.actionLabel : Ui(UiText::Open);
    } else {
        // The legacy Vista task text is translated with official Windows
        // terminology. The added hover panel reuses that concise localized
        // description so no English-only explanatory copy leaks into it.
        it.detailTitle = it.title;
        it.detailBody = it.description;
        it.actionLabel = Ui(UiText::Open);
    }
    return it;
}

static void RebuildItems() {
    g.gettingStarted.clear();
    g.offers.clear();
    g.oem.clear();
    static_assert(ARRAYSIZE(kGettingStarted) ==
                  static_cast<size_t>(TaskTextId::MicrosoftAccount));
    static_assert(ARRAYSIZE(kGettingStarted) + ARRAYSIZE(kOffers) ==
                  static_cast<size_t>(TaskTextId::Count));
    for (size_t i = 0; i < ARRAYSIZE(kGettingStarted); ++i) {
        const auto& d = kGettingStarted[i];
        if (d.hidden) {
            continue;
        }
        g.gettingStarted.push_back(FromDef(
            d, static_cast<TaskTextId>(i), g.settings.vistaItemNames));
    }
    if (g.settings.showOffers) {
        const size_t offset = static_cast<size_t>(TaskTextId::MicrosoftAccount);
        for (size_t i = 0; i < ARRAYSIZE(kOffers); ++i) {
            g.offers.push_back(FromDef(
                kOffers[i], static_cast<TaskTextId>(offset + i),
                g.settings.vistaItemNames));
        }
    }
    for (const auto& o : g.settings.oemLinks) {
        Item it;
        it.title = o.title;
        it.description = o.description.empty()
                             ? Ui(UiText::CustomOemDescription)
                             : o.description;
        it.userTarget = o.target;
        it.icon = SIID_LINK;
        it.oem = true;
        g.oem.push_back(std::move(it));
    }
}

static std::vector<Item>& ItemsOf(int section) {
    if (section == static_cast<int>(SectionId::Offers)) {
        return g.offers;
    }
    if (section == static_cast<int>(SectionId::Oem)) {
        return g.oem;
    }
    return g.gettingStarted;
}

static void ClearSelectedItem() {
    g.selectedSection = -1;
    g.selectedIndex = -1;
}

static void ValidateSelectedItem() {
    if (g.selectedSection < 0 || g.selectedIndex < 0) {
        ClearSelectedItem();
        return;
    }
    auto& items = ItemsOf(g.selectedSection);
    if (g.selectedIndex >= static_cast<int>(items.size())) {
        ClearSelectedItem();
    }
}

static const wchar_t* LocalizedOemSectionTitle() {
    if (g.settings.oemSectionTitle.empty() ||
        EqualsIgnoreCase(g.settings.oemSectionTitle.c_str(),
                         L"Offers from your computer manufacturer")) {
        return Ui(UiText::DefaultOem);
    }
    return g.settings.oemSectionTitle.c_str();
}

static const wchar_t* SectionTitle(int section, int count) {
    static wchar_t buf[192];
    const wchar_t* title = nullptr;
    if (section == static_cast<int>(SectionId::GettingStarted)) {
        title = Ui(IsWindows7Style() ? UiText::SectionGetting
                                     : UiText::SectionGetWindows);
    } else if (section == static_cast<int>(SectionId::Offers)) {
        title = Ui(UiText::OffersMicrosoft);
    } else {
        title = LocalizedOemSectionTitle();
    }
    if (IsWindows7Style()) {
        swprintf_s(buf, L"%s (%d)", title, count);
    } else {
        const int n = section == static_cast<int>(SectionId::GettingStarted)
                          ? 1
                          : (section == static_cast<int>(SectionId::Offers)
                                 ? 2
                                 : (g.offers.empty() ? 2 : 3));
        swprintf_s(buf, L"%d. %s (%d)", n, title, count);
    }
    return buf;
}

// ---------------------------------------------------------------------------
// Layout
// ---------------------------------------------------------------------------

struct Layout {
    int pad = 0;
    int headerH = 0;
    int footerH = 0;
    int descH = 0;
    int sectionH = 0;
    int showAllH = 0;
    int itemH = 0;
    int icon = 0;
    int userTile = 0;
    int userBarH = 0;
    RECT header{};
    RECT tasks{};
    RECT desc{};
    RECT footer{};
    RECT showMore{};
    RECT oemLogo{};
    RECT userBar{};
    RECT userPic{};
    RECT userName{};
    RECT pcArt{};
    RECT info{};
};

static Layout ComputeLayout(int cw, int ch, UINT dpi) {
    Layout L;
    const bool win7 = IsWindows7Style();
    L.pad = ScalePx(12, dpi);
    L.headerH = ScalePx(win7 ? 178 : 168, dpi);
    // Translated startup guidance can be substantially longer than English.
    // Give it a multiline footer instead of clipping it at narrow widths.
    L.footerH = ScalePx(g_activeLanguage == UiLanguage::English ? 32 : 58, dpi);
    L.descH = ScalePx(22, dpi);
    L.sectionH = ScalePx(win7 ? 20 : 22, dpi);
    L.showAllH = ScalePx(20, dpi);
    L.itemH = ScalePx(win7 ? 58 : 56, dpi);
    L.icon = ScalePx(48, dpi);
    L.userBarH = win7 ? 0 : ScalePx(52, dpi);
    // Full frame bitmap including its own shadow; photo well is inside it.
    L.userTile = win7 ? 0 : ScalePx(46, dpi);
    const int outer = L.userTile;

    L.header = {0, 0, cw, L.headerH};
    L.footer = {0, ch - L.footerH, cw, ch};
    L.desc = {0, L.footer.top - L.descH, cw, L.footer.top};
    L.tasks = {0, L.headerH, cw, L.desc.top};

    if (win7) {
        // Windows 7 Getting Started used a pale blue hero panel: artwork on
        // the left, descriptive copy in the middle, and an action on the
        // right. Keep that geometry at every DPI and window width.
        const int actionW = ScalePx(198, dpi);
        const int artRight = IMin(cw / 3, ScalePx(150, dpi));
        L.userBar = {0, 0, 0, 0};
        L.userPic = {0, 0, 0, 0};
        L.userName = {0, 0, 0, 0};
        L.oemLogo = {0, 0, 0, 0};
        L.pcArt = {ScalePx(14, dpi), ScalePx(9, dpi), artRight,
                   L.headerH - ScalePx(8, dpi)};
        L.showMore = {IMax(L.pcArt.right + ScalePx(150, dpi), cw - actionW),
                      ScalePx(50, dpi), cw - L.pad, ScalePx(82, dpi)};
        L.info = {L.pcArt.right + ScalePx(8, dpi), ScalePx(16, dpi),
                  L.showMore.left - ScalePx(10, dpi),
                  L.headerH - ScalePx(12, dpi)};
        return L;
    }

    L.userBar = {0, 0, cw, L.userBarH};
    const int picY = IMax(ScalePx(3, dpi), (L.userBarH - outer) / 2);
    L.userPic = {L.pad, picY, L.pad + outer, picY + outer};
    const int logoSlot = g.sys.oemLogo[0] ? ScalePx(72, dpi) : 0;
    L.oemLogo = {cw - L.pad - logoSlot, ScalePx(4, dpi), cw - L.pad,
                 L.userBarH - ScalePx(4, dpi)};
    L.userName = {L.userPic.right + ScalePx(8, dpi), 0,
                  (logoSlot ? L.oemLogo.left - ScalePx(8, dpi) : cw - L.pad),
                  L.userBarH};
    L.pcArt = {ScalePx(8, dpi), L.userBarH + ScalePx(2, dpi), ScalePx(220, dpi),
               L.headerH - ScalePx(4, dpi)};
    L.info = {L.pcArt.right + ScalePx(10, dpi), L.userBarH + ScalePx(16, dpi),
              cw - ScalePx(200, dpi), L.headerH - ScalePx(16, dpi)};
    L.showMore = {cw - ScalePx(196, dpi), L.userBarH + ScalePx(14, dpi), cw - L.pad,
                  L.userBarH + ScalePx(36, dpi)};
    return L;
}

static RECT MirrorRectHorizontally(const RECT& rect, int width) {
    return RECT{width - rect.right, rect.top, width - rect.left,
                rect.bottom};
}

static Layout ComputeLocalizedLayout(int cw, int ch, UINT dpi) {
    Layout layout = ComputeLayout(cw, ch, dpi);
    if (!IsRtlLanguage()) {
        return layout;
    }
    layout.header = MirrorRectHorizontally(layout.header, cw);
    layout.tasks = MirrorRectHorizontally(layout.tasks, cw);
    layout.desc = MirrorRectHorizontally(layout.desc, cw);
    layout.footer = MirrorRectHorizontally(layout.footer, cw);
    layout.showMore = MirrorRectHorizontally(layout.showMore, cw);
    layout.oemLogo = MirrorRectHorizontally(layout.oemLogo, cw);
    layout.userBar = MirrorRectHorizontally(layout.userBar, cw);
    layout.userPic = MirrorRectHorizontally(layout.userPic, cw);
    layout.userName = MirrorRectHorizontally(layout.userName, cw);
    layout.pcArt = MirrorRectHorizontally(layout.pcArt, cw);
    layout.info = MirrorRectHorizontally(layout.info, cw);
    return layout;
}

// ---------------------------------------------------------------------------
// GDI+ drawing
// ---------------------------------------------------------------------------

static Gdiplus::Rect ToG(const RECT& r) {
    return Gdiplus::Rect(r.left, r.top, r.right - r.left, r.bottom - r.top);
}

static void ApplyStringDirection(Gdiplus::StringFormat* format) {
    if (format && IsRtlLanguage()) {
        format->SetFormatFlags(format->GetFormatFlags() |
                               Gdiplus::StringFormatFlagsDirectionRightToLeft);
    }
}

static const Gdiplus::FontFamily* GetSegoeFontFamily() {
    if (!g.segoeFamily) {
        g.segoeFamily = new Gdiplus::FontFamily(L"Segoe UI");
    }
    return g.segoeFamily;
}

static void DrawStringG(Gdiplus::Graphics& gr, const wchar_t* text,
                        const Gdiplus::Font& font, const Gdiplus::Brush& brush,
                        const Gdiplus::RectF& rc, INT align = 0,
                        bool wrap = true) {
    Gdiplus::StringFormat fmt;
    fmt.SetAlignment(static_cast<Gdiplus::StringAlignment>(align));
    fmt.SetLineAlignment(Gdiplus::StringAlignmentNear);
    fmt.SetTrimming(Gdiplus::StringTrimmingEllipsisWord);
    if (!wrap) {
        fmt.SetFormatFlags(fmt.GetFormatFlags() |
                           Gdiplus::StringFormatFlagsNoWrap);
    }
    ApplyStringDirection(&fmt);
    gr.DrawString(text, -1, &font, rc, &fmt, &brush);
}

