static int B64Val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

// Padding-safe decoder, same rules as the Win7 Network Flyout: skip
// whitespace, treat '=' as end-of-payload, ignore a second concatenated
// blob after padding.
static bool DecodeBase64(const char* src, std::vector<BYTE>* out) {
    if (!src || !out) {
        return false;
    }
    out->clear();
    const size_t srcLen = strlen(src);
    out->reserve((srcLen * 3) / 4 + 4);
    int val = 0;
    int valb = -8;
    bool seenPadding = false;
    for (const char* p = src; *p; ++p) {
        const char c = *p;
        if (c == '=') {
            seenPadding = true;
            continue;
        }
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t') {
            continue;
        }
        if (seenPadding) {
            break;
        }
        const int d = B64Val(c);
        if (d < 0) {
            continue;
        }
        val = (val << 6) + d;
        valb += 6;
        if (valb >= 0) {
            out->push_back(static_cast<BYTE>((val >> valb) & 0xFF));
            valb -= 8;
        }
    }
    return !out->empty();
}

// ---------------------------------------------------------------------------
// Isolated asset loader (Network Flyout style)
// User files in the Windhawk storage folder / optional custom folder win.
// Embedded Base64 is the fallback. Never reads or writes %SystemRoot%.
// ---------------------------------------------------------------------------

static constexpr DWORD kMaxAssetBytes = 8u * 1024u * 1024u;
static constexpr DWORD kMaxLauncherBytes = 2u * 1024u * 1024u;

static Gdiplus::Bitmap* LoadPngFromBase64(const char* b64);
static bool GetWelcomeCenterDir(wchar_t* dir, size_t cch) {
    if (!dir || cch == 0) {
        return false;
    }
    dir[0] = 0;
    wchar_t base[MAX_PATH] = {};
    const DWORD n = GetEnvironmentVariableW(L"LOCALAPPDATA", base, MAX_PATH);
    if (n == 0 || n >= MAX_PATH) {
        return false;
    }
    return swprintf_s(dir, cch, L"%s\\WelcomeCenter", base) >= 0;
}

static bool IsUnderWindowsDir(const wchar_t* path) {
    if (!path || !*path) {
        return true;
    }
    wchar_t win[MAX_PATH] = {};
    const UINT n = GetSystemWindowsDirectoryW(win, MAX_PATH);
    if (!n || n >= MAX_PATH) {
        return true;
    }
    size_t wn = wcslen(win);
    if (wn && win[wn - 1] != L'\\' && wn + 1 < MAX_PATH) {
        win[wn] = L'\\';
        win[wn + 1] = 0;
        ++wn;
    }
    return _wcsnicmp(path, win, wn) == 0;
}

static bool DirExistsW(const wchar_t* path) {
    if (!path || !*path) {
        return false;
    }
    const DWORD a = GetFileAttributesW(path);
    return a != INVALID_FILE_ATTRIBUTES && (a & FILE_ATTRIBUTE_DIRECTORY);
}

static bool SanitizeUserFolder(const wchar_t* raw, wchar_t* out, size_t cch) {
    if (!raw || !*raw || !out || cch == 0 || HasPathMeta(raw)) {
        return false;
    }
    wchar_t expanded[MAX_PATH] = {};
    if (!ExpandEnvironmentStringsW(raw, expanded, MAX_PATH) || !expanded[0]) {
        return false;
    }
    wchar_t full[MAX_PATH] = {};
    const DWORD n = GetFullPathNameW(expanded, MAX_PATH, full, nullptr);
    if (n == 0 || n >= MAX_PATH) {
        return false;
    }
    if (full[0] == L'\\' && full[1] == L'\\') {
        return false;
    }
    if (!DirExistsW(full) || IsUnderWindowsDir(full)) {
        Wh_Log(L"Rejected resource folder: %s", full);
        return false;
    }
    CopyTrunc(out, cch, full);
    return true;
}

static bool GetWhStorageDir(wchar_t* dir, size_t cch) {
    if (!dir || cch == 0) {
        return false;
    }
    dir[0] = 0;
    const size_t n = Wh_GetModStoragePath(dir, cch);
    if (n == 0 || !dir[0]) {
        return false;
    }
    if (IsUnderWindowsDir(dir)) {
        dir[0] = 0;
        return false;
    }
    CreateDirectoryW(dir, nullptr);
    return DirExistsW(dir);
}

static bool JoinPath(wchar_t* out, size_t cch, const wchar_t* dir,
                     const wchar_t* name) {
    if (!out || !dir || !name || cch == 0 || wcschr(name, L'\\') ||
        wcschr(name, L'/') || wcsstr(name, L"..")) {
        return false;
    }
    return swprintf_s(out, cch, L"%s\\%s", dir, name) >= 0;
}

static bool FileSizeOk(const wchar_t* path, DWORD maxBytes, DWORD* outSize) {
    WIN32_FILE_ATTRIBUTE_DATA fad{};
    if (!GetFileAttributesExW(path, GetFileExInfoStandard, &fad)) {
        return false;
    }
    if (fad.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) {
        return false;
    }
    if (fad.nFileSizeHigh != 0 || fad.nFileSizeLow == 0 ||
        fad.nFileSizeLow > maxBytes) {
        return false;
    }
    if (outSize) {
        *outSize = fad.nFileSizeLow;
    }
    return true;
}

static bool LooksLikeAssetName(const wchar_t* name, bool allowExe) {
    const wchar_t* ext = PathFindExtensionW(name);
    if (!ext || !*ext) {
        return false;
    }
    if (EqualsIgnoreCase(ext, L".png") || EqualsIgnoreCase(ext, L".jpg") ||
        EqualsIgnoreCase(ext, L".jpeg") || EqualsIgnoreCase(ext, L".bmp") ||
        EqualsIgnoreCase(ext, L".gif") || EqualsIgnoreCase(ext, L".ico")) {
        return true;
    }
    return allowExe && EqualsIgnoreCase(ext, L".exe");
}

static bool PushSearchDir(wchar_t dirs[][MAX_PATH], int* count, int max,
                          const wchar_t* dir) {
    if (!dir || !*dir || !count || *count >= max || !DirExistsW(dir) ||
        IsUnderWindowsDir(dir)) {
        return false;
    }
    for (int i = 0; i < *count; ++i) {
        if (EqualsIgnoreCase(dirs[i], dir)) {
            return false;
        }
    }
    CopyTrunc(dirs[*count], MAX_PATH, dir);
    ++(*count);
    return true;
}

static int CollectAssetSearchDirs(wchar_t dirs[][MAX_PATH], int max) {
    int n = 0;
    wchar_t custom[MAX_PATH] = {};
    if (SanitizeUserFolder(g.settings.resourceFolder.c_str(), custom,
                           MAX_PATH)) {
        PushSearchDir(dirs, &n, max, custom);
        wchar_t sub[MAX_PATH] = {};
        if (JoinPath(sub, MAX_PATH, custom, L"resources")) {
            PushSearchDir(dirs, &n, max, sub);
        }
    }
    wchar_t storage[MAX_PATH] = {};
    if (GetWhStorageDir(storage, MAX_PATH)) {
        PushSearchDir(dirs, &n, max, storage);
        wchar_t sub[MAX_PATH] = {};
        if (JoinPath(sub, MAX_PATH, storage, L"resources")) {
            PushSearchDir(dirs, &n, max, sub);
        }
    }
    wchar_t local[MAX_PATH] = {};
    if (GetWelcomeCenterDir(local, MAX_PATH)) {
        PushSearchDir(dirs, &n, max, local);
        wchar_t sub[MAX_PATH] = {};
        if (JoinPath(sub, MAX_PATH, local, L"resources")) {
            PushSearchDir(dirs, &n, max, sub);
        }
    }
    return n;
}

struct AssetNameList {
    const wchar_t* logical;
    const wchar_t* names[6];
    bool allowExe;
};

static const AssetNameList kAssetNames[] = {
    {L"aurora", {L"aurora.png", L"aurora.jpg", L"aurora.jpeg", L"header.png",
                 L"header.jpg", nullptr}, false},
    {L"pc", {L"pc.png", L"computer.png", L"vista-pc.png", nullptr}, false},
    {L"chevron", {L"chevron.png", L"showmore.png", nullptr}, false},
    {L"arrow", {L"arrow.png", L"green-arrow.png", L"arrow-green.png", nullptr}, false},
    {L"user-frame",
     {L"user-frame.png", L"userframe.png", L"frame.png", nullptr}, false},
    {L"app", {L"app.png", L"icon.png", nullptr}, false},
    {L"app-ico", {L"app.ico", nullptr}, false},
    {L"personalize", {L"personalize.png", nullptr}, false},
    {L"power", {L"power.png", L"power-options.png", nullptr}, false},
    {L"sound", {L"sound.png", L"audio.png", nullptr}, false},
    {L"ease", {L"ease.png", L"ease-of-access.png", nullptr}, false},
    {L"transfer", {L"transfer.png", L"easy-transfer.png", nullptr}, false},
    {L"default-programs",
     {L"default-programs.png", L"defaults.png", nullptr}, false},
    {L"surf", {L"surf.png", L"browser.png", nullptr}, false},
    {L"details", {L"details.png", L"more-details.png", nullptr}, false},
    {L"store", {L"store.png", L"marketplace.png", nullptr}, false},
};

static const AssetNameList* FindAssetList(const wchar_t* logical) {
    if (!logical) {
        return nullptr;
    }
    for (const auto& a : kAssetNames) {
        if (EqualsIgnoreCase(a.logical, logical)) {
            return &a;
        }
    }
    return nullptr;
}

static bool FindUserAsset(const wchar_t* logical, wchar_t* out, size_t cch) {
    if (!out || cch == 0) {
        return false;
    }
    out[0] = 0;
    const AssetNameList* list = FindAssetList(logical);
    if (!list) {
        return false;
    }
    wchar_t dirs[8][MAX_PATH] = {};
    const int nd = CollectAssetSearchDirs(dirs, 8);
    for (int d = 0; d < nd; ++d) {
        for (int i = 0; i < 6 && list->names[i]; ++i) {
            const wchar_t* name = list->names[i];
            if (!LooksLikeAssetName(name, list->allowExe)) {
                continue;
            }
            wchar_t path[MAX_PATH] = {};
            if (!JoinPath(path, MAX_PATH, dirs[d], name)) {
                continue;
            }
            const DWORD cap =
                list->allowExe ? kMaxLauncherBytes : kMaxAssetBytes;
            if (FileExistsW(path) && FileSizeOk(path, cap, nullptr)) {
                CopyTrunc(out, cch, path);
                return true;
            }
        }
    }
    return false;
}

static Gdiplus::Bitmap* LoadBitmapFromDisk(const wchar_t* path) {
    if (!FileExistsW(path) || !FileSizeOk(path, kMaxAssetBytes, nullptr)) {
        return nullptr;
    }
    Gdiplus::Bitmap* bmp = nullptr;
    try {
        bmp = Gdiplus::Bitmap::FromFile(path, FALSE);
    } catch (...) {
        Wh_Log(L"GDI+ FromFile threw: %s", path);
        return nullptr;
    }
    if (!bmp || bmp->GetLastStatus() != Gdiplus::Ok) {
        delete bmp;
        Wh_Log(L"GDI+ image load failed: %s", path);
        return nullptr;
    }
    return bmp;
}

static bool FileStartsWithMz(const wchar_t* path) {
    UniqueHandle f(CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, nullptr,
                               OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr));
    if (!f || f.get() == INVALID_HANDLE_VALUE) {
        return false;
    }
    char magic[2] = {};
    DWORD read = 0;
    if (!ReadFile(f.get(), magic, 2, &read, nullptr) || read != 2) {
        return false;
    }
    return magic[0] == 'M' && magic[1] == 'Z';
}

static Gdiplus::Bitmap* LoadModBitmap(Gdiplus::Bitmap*& slot,
                                      const wchar_t* logical,
                                      const char* embed) {
    if (slot) {
        return slot;
    }
    wchar_t path[MAX_PATH] = {};
    if (FindUserAsset(logical, path, MAX_PATH)) {
        slot = LoadBitmapFromDisk(path);
        if (slot) {
            Wh_Log(L"Asset '%s' from file: %s", logical, path);
            return slot;
        }
        Wh_Log(L"Asset '%s' file failed (%s); using embed", logical, path);
    }
    if (embed && *embed) {
        slot = LoadPngFromBase64(embed);
    }
    return slot;
}

static Gdiplus::Bitmap* LoadPngFromBase64(const char* b64) {
    if (!b64 || !*b64) {
        return nullptr;
    }
    std::vector<BYTE> bytes;
    if (!DecodeBase64(b64, &bytes) || bytes.empty()) {
        Wh_Log(L"Embedded image base64 decode failed");
        return nullptr;
    }
    HGLOBAL mem = GlobalAlloc(GMEM_MOVEABLE, bytes.size());
    if (!mem) {
        Wh_Log(L"GlobalAlloc failed for embedded image");
        return nullptr;
    }
    void* p = GlobalLock(mem);
    if (!p) {
        GlobalFree(mem);
        return nullptr;
    }
    memcpy(p, bytes.data(), bytes.size());
    GlobalUnlock(mem);
    UniqueCom<IStream> stream;
    if (FAILED(CreateStreamOnHGlobal(mem, TRUE, stream.put())) || !stream) {
        GlobalFree(mem);
        return nullptr;
    }
    // CreateStreamOnHGlobal(TRUE) takes ownership of mem.
    Gdiplus::Bitmap* bmp = nullptr;
    try {
        bmp = Gdiplus::Bitmap::FromStream(stream.get());
    } catch (...) {
        Wh_Log(L"GDI+ FromStream threw");
        return nullptr;
    }
    if (!bmp || bmp->GetLastStatus() != Gdiplus::Ok) {
        delete bmp;
        Wh_Log(L"GDI+ image load failed");
        return nullptr;
    }
    return bmp;
}

