static Gdiplus::Bitmap* GetVistaPcBitmap() {
    return LoadModBitmap(g.pcBitmap, L"pc", kVistaPcPngB64);
}

static Gdiplus::Bitmap* GetStoreBitmap() {
    return LoadModBitmap(g.storeBitmap, L"store", kStorePngB64);
}

static const wchar_t* LogicalFromEmbed(const char* b64) {
    if (b64 == kStorePngB64) {
        return L"store";
    }
    if (b64 == kPersonalizePngB64) {
        return L"personalize";
    }
    if (b64 == kPowerOptionsPngB64) {
        return L"power";
    }
    if (b64 == kSoundPngB64) {
        return L"sound";
    }
    if (b64 == kEasePngB64) {
        return L"ease";
    }
    if (b64 == kTransferPngB64) {
        return L"transfer";
    }
    if (b64 == kDefaultPngB64) {
        return L"default-programs";
    }
    if (b64 == kSurfPngB64) {
        return L"surf";
    }
    if (b64 == kDetailsPngB64 || b64 == kAppIconPngB64) {
        // The former Windows 7 main monitor icon now belongs to the
        // View computer details task and follows details.png overrides.
        return L"details";
    }
    if (b64 == kVistaAppIconPngB64) {
        return L"app";
    }
    if (b64 == kVistaPcPngB64) {
        return L"pc";
    }
    if (b64 == kGreenArrowPngB64) {
        return L"arrow";
    }
    return nullptr;
}

static Gdiplus::Bitmap* GetEmbedBitmap(const char* b64) {
    if (!b64) {
        return nullptr;
    }
    if (b64 == kStorePngB64) {
        return GetStoreBitmap();
    }
    const wchar_t* logical = LogicalFromEmbed(b64);
    for (auto& e : g.embedBitmaps) {
        if (e.first == b64) {
            return e.second;
        }
    }
    Gdiplus::Bitmap* bmp = nullptr;
    if (logical) {
        wchar_t path[MAX_PATH] = {};
        if (FindUserAsset(logical, path, MAX_PATH)) {
            bmp = LoadBitmapFromDisk(path);
            if (bmp) {
                Wh_Log(L"Tile '%s' from file: %s", logical, path);
            }
        }
    }
    if (!bmp) {
        bmp = LoadPngFromBase64(b64);
    }
    if (bmp) {
        g.embedBitmaps.push_back({b64, bmp});
    }
    return bmp;
}


static const char* SelectedAppIconPngBase64() {
    // Keep every main-icon integration identical across both appearances.
    return kVistaAppIconPngB64;
}

static const char* SelectedAppIconIcoBase64() {
    return kVistaAppIconIcoB64;
}

static HICON GetAppHicon() {
    if (g.appIcon) {
        return g.appIcon;
    }
    Gdiplus::Bitmap* bmp = GetEmbedBitmap(SelectedAppIconPngBase64());
    if (!bmp) {
        return LoadStockIcon(SIID_DESKTOPPC);
    }
    HICON icon = nullptr;
    if (bmp->GetHICON(&icon) != Gdiplus::Ok || !icon) {
        return LoadStockIcon(SIID_DESKTOPPC);
    }
    g.appIcon = icon;
    return icon;
}

static bool FileEqualsBytes(const wchar_t* path,
                            const std::vector<BYTE>& expected) {
    if (!path || !*path || expected.empty() || expected.size() > MAXDWORD) {
        return false;
    }
    WIN32_FILE_ATTRIBUTE_DATA data{};
    if (!GetFileAttributesExW(path, GetFileExInfoStandard, &data) ||
        data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY ||
        data.nFileSizeHigh != 0 || data.nFileSizeLow != expected.size()) {
        return false;
    }
    UniqueHandle file(CreateFileW(
        path, GENERIC_READ,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr));
    if (!file || file.get() == INVALID_HANDLE_VALUE) {
        return false;
    }
    BYTE chunk[4096];
    size_t offset = 0;
    while (offset < expected.size()) {
        const size_t remaining = expected.size() - offset;
        const DWORD want = static_cast<DWORD>(
            remaining < sizeof(chunk) ? remaining : sizeof(chunk));
        DWORD got = 0;
        if (!ReadFile(file.get(), chunk, want, &got, nullptr) || got != want ||
            memcmp(chunk, expected.data() + offset, want) != 0) {
            return false;
        }
        offset += got;
    }
    return true;
}

static bool FindUserAppIconFile(wchar_t* path, size_t cch) {
    if (!FindUserAsset(L"app-ico", path, cch)) {
        return false;
    }

    // Builds through 1.0.51 generated app.ico in this same user-writable
    // directory. Do not mistake that known byte-for-byte file for a custom
    // override after introducing per-skin icon files. A genuinely different
    // app.ico remains user-owned and continues to override both skins.
    wchar_t dir[MAX_PATH] = {};
    wchar_t legacy[MAX_PATH] = {};
    std::vector<BYTE> oldEmbedded;
    if (GetWelcomeCenterDir(dir, ARRAYSIZE(dir)) &&
        JoinPath(legacy, ARRAYSIZE(legacy), dir, L"app.ico") &&
        EqualsIgnoreCase(path, legacy) &&
        DecodeBase64(kAppIconIcoB64, &oldEmbedded) &&
        FileEqualsBytes(path, oldEmbedded)) {
        if (!DeleteFileW(path) && GetLastError() != ERROR_FILE_NOT_FOUND) {
            Wh_Log(L"Could not remove legacy generated app.ico (%u)",
                   GetLastError());
        } else {
            Wh_Log(L"Migrated legacy generated app.ico to per-skin icons");
        }
        path[0] = 0;
        return false;
    }
    return true;
}

static bool GetAppIconFilePath(wchar_t* path, size_t cch) {
    wchar_t dir[MAX_PATH] = {};
    if (!GetWelcomeCenterDir(dir, ARRAYSIZE(dir))) {
        return false;
    }
    // Retain the established per-appearance paths so existing integrations
    // migrate in place. EnsureAppIconFile refreshes either file from the same
    // CP003 bytes and replaces an older generated Windows 7 icon safely.
    return JoinPath(path, cch, dir,
                    IsWindows7Style() ? L"app-windows7.ico"
                                      : L"app-vista.ico");
}

static bool EnsureAppIconFile(wchar_t* path, size_t cch) {
    if (!path || cch == 0) {
        return false;
    }
    path[0] = 0;
    if (FindUserAppIconFile(path, cch)) {
        return true;
    }
    if (!GetAppIconFilePath(path, cch)) {
        return false;
    }
    std::vector<BYTE> bytes;
    if (!DecodeBase64(SelectedAppIconIcoBase64(), &bytes) || bytes.empty() ||
        bytes.size() > MAXDWORD) {
        Wh_Log(L"Embedded application icon decode failed");
        path[0] = 0;
        return false;
    }
    if (FileEqualsBytes(path, bytes)) {
        return true;
    }
    // Write beside the destination and replace it only after a complete,
    // flushed write. This preserves a usable existing integration icon if an
    // update is interrupted and safely migrates app-windows7.ico to CP003.
    wchar_t temporary[MAX_PATH] = {};
    if (swprintf_s(temporary, ARRAYSIZE(temporary), L"%s.%lu.tmp", path,
                   GetCurrentProcessId()) <= 0) {
        Wh_Log(L"Temporary application icon path is too long");
        path[0] = 0;
        return false;
    }
    UniqueHandle file(CreateFileW(temporary, GENERIC_WRITE, 0, nullptr,
                                  CREATE_ALWAYS,
                                  FILE_ATTRIBUTE_TEMPORARY, nullptr));
    if (!file || file.get() == INVALID_HANDLE_VALUE) {
        Wh_Log(L"CreateFile application icon failed (%u)", GetLastError());
        path[0] = 0;
        return false;
    }
    DWORD written = 0;
    const BOOL wrote = WriteFile(file.get(), bytes.data(),
                                 static_cast<DWORD>(bytes.size()), &written,
                                 nullptr);
    const DWORD writeError = wrote ? ERROR_SUCCESS : GetLastError();
    if (!wrote || written != bytes.size()) {
        const DWORD error = wrote ? ERROR_WRITE_FAULT : writeError;
        Wh_Log(L"WriteFile application icon failed (%u)", error);
        file.reset();
        DeleteFileW(temporary);
        path[0] = 0;
        return false;
    }
    if (!FlushFileBuffers(file.get())) {
        const DWORD error = GetLastError();
        Wh_Log(L"Flush application icon failed (%u)", error);
        file.reset();
        DeleteFileW(temporary);
        path[0] = 0;
        return false;
    }
    file.reset();
    if (!MoveFileExW(temporary, path,
                     MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)) {
        const DWORD error = GetLastError();
        Wh_Log(L"Replace application icon failed (%u)", error);
        DeleteFileW(temporary);
        path[0] = 0;
        return false;
    }
    return true;
}

static void DrawEmbeddedPng(Gdiplus::Graphics& gr, Gdiplus::Bitmap* bmp,
                            const RECT& rc) {
    using namespace Gdiplus;
    if (!bmp) {
        return;
    }
    const INT iw = static_cast<INT>(bmp->GetWidth());
    const INT ih = static_cast<INT>(bmp->GetHeight());
    if (iw <= 0 || ih <= 0) {
        return;
    }
    const INT boxW = rc.right - rc.left;
    const INT boxH = rc.bottom - rc.top;
    const REAL sx = static_cast<REAL>(boxW) / static_cast<REAL>(iw);
    const REAL sy = static_cast<REAL>(boxH) / static_cast<REAL>(ih);
    const REAL scale = (sx < sy) ? sx : sy;
    const INT dw = static_cast<INT>(iw * scale);
    const INT dh = static_cast<INT>(ih * scale);
    const INT dx = rc.left + (boxW - dw) / 2;
    const INT dy = rc.top + (boxH - dh) / 2;
    gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    gr.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    gr.DrawImage(bmp, dx, dy, dw, dh);
}

static void DrawItemIcon(Gdiplus::Graphics& gr, const Item& item,
                         const RECT& rc) {
    if (EqualsIgnoreCase(item.settingsUri.c_str(),
                         kInternalMediaPlayerLegacy)) {
        if (Gdiplus::Bitmap* bmp = GetMediaPlayerIconBitmap()) {
            DrawEmbeddedPng(gr, bmp, rc);
            return;
        }
    }
    if (item.embedPng) {
        DrawEmbeddedPng(gr, GetEmbedBitmap(item.embedPng), rc);
    } else {
        DrawStockIconG(gr, item.icon, rc);
    }
}

static void DrawPcIllustration(Gdiplus::Graphics& gr, const RECT& rc) {
    using namespace Gdiplus;
    const INT boxW = rc.right - rc.left;
    const INT boxH = rc.bottom - rc.top;
    if (boxW < 8 || boxH < 8) {
        return;
    }

    Bitmap* bmp = GetVistaPcBitmap();
    if (!bmp) {
        return;
    }

    const INT iw = static_cast<INT>(bmp->GetWidth());
    const INT ih = static_cast<INT>(bmp->GetHeight());
    if (iw <= 0 || ih <= 0) {
        return;
    }

    // Fit HD art into the header slot, preserve aspect, bottom-align.
    const REAL sx = static_cast<REAL>(boxW) / static_cast<REAL>(iw);
    const REAL sy = static_cast<REAL>(boxH) / static_cast<REAL>(ih);
    const REAL scale = (sx < sy) ? sx : sy;
    const INT dw = static_cast<INT>(iw * scale);
    const INT dh = static_cast<INT>(ih * scale);
    const INT dx = rc.left + (boxW - dw) / 2;
    const INT dy = rc.bottom - dh;

    gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    gr.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    gr.SetSmoothingMode(SmoothingModeHighQuality);
    gr.DrawImage(bmp, dx, dy, dw, dh);
}

static bool FindLargestEmbeddedImage(const BYTE* p, size_t n, size_t* off,
                                     size_t* len) {
    size_t bestOff = 0;
    size_t bestLen = 0;
    for (size_t i = 0; i + 3 < n; ++i) {
        if (p[i] == 0xFF && p[i + 1] == 0xD8 && p[i + 2] == 0xFF) {
            for (size_t j = i + 3; j + 1 < n; ++j) {
                if (p[j] == 0xFF && p[j + 1] == 0xD9) {
                    const size_t L = j + 2 - i;
                    if (L > bestLen) {
                        bestLen = L;
                        bestOff = i;
                    }
                    break;
                }
            }
        }
        if (i + 8 < n && p[i] == 0x89 && p[i + 1] == 'P' && p[i + 2] == 'N' &&
            p[i + 3] == 'G') {
            for (size_t j = i + 8; j + 8 < n; ++j) {
                if (p[j] == 0x49 && p[j + 1] == 0x45 && p[j + 2] == 0x4E &&
                    p[j + 3] == 0x44) {
                    const size_t L = j + 8 - i;
                    if (L > bestLen) {
                        bestLen = L;
                        bestOff = i;
                    }
                    break;
                }
            }
        }
        if (p[i] == 'B' && p[i + 1] == 'M' && i + 6 < n) {
            const size_t L = static_cast<size_t>(p[i + 2] | (p[i + 3] << 8) |
                                                 (p[i + 4] << 16) |
                                                 (p[i + 5] << 24));
            if (L >= 54 && i + L <= n && L > bestLen) {
                bestLen = L;
                bestOff = i;
            }
        }
    }
    if (bestLen < 32) {
        return false;
    }
    *off = bestOff;
    *len = bestLen;
    return true;
}

static Gdiplus::Bitmap* BitmapFromMemory(const BYTE* data, size_t len) {
    if (!data || len == 0) {
        return nullptr;
    }
    HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, len);
    if (!hg) {
        return nullptr;
    }
    void* locked = GlobalLock(hg);
    if (!locked) {
        GlobalFree(hg);
        return nullptr;
    }
    memcpy(locked, data, len);
    GlobalUnlock(hg);
    IStream* st = nullptr;
    if (FAILED(CreateStreamOnHGlobal(hg, TRUE, &st)) || !st) {
        GlobalFree(hg);
        return nullptr;
    }
    auto* bmp = Gdiplus::Bitmap::FromStream(st);
    st->Release();
    if (!bmp || bmp->GetLastStatus() != Gdiplus::Ok) {
        delete bmp;
        return nullptr;
    }
    return bmp;
}

static Gdiplus::Bitmap* LoadAccountPictureContainer(const wchar_t* path) {
    HANDLE f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, nullptr,
                           OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (f == INVALID_HANDLE_VALUE) {
        return nullptr;
    }
    LARGE_INTEGER sz{};
    if (!GetFileSizeEx(f, &sz) || sz.QuadPart <= 0 || sz.QuadPart > 8 * 1024 * 1024) {
        CloseHandle(f);
        return nullptr;
    }
    std::vector<BYTE> raw(static_cast<size_t>(sz.QuadPart));
    DWORD rd = 0;
    const BOOL ok = ReadFile(f, raw.data(), static_cast<DWORD>(raw.size()), &rd, nullptr);
    CloseHandle(f);
    if (!ok || rd < 32) {
        return nullptr;
    }
    size_t off = 0, len = 0;
    if (!FindLargestEmbeddedImage(raw.data(), rd, &off, &len)) {
        return nullptr;
    }
    return BitmapFromMemory(raw.data() + off, len);
}

static Gdiplus::Bitmap* LoadUserPictureFile(const wchar_t* path) {
    if (!path || !*path) {
        return nullptr;
    }
    const wchar_t* ext = PathFindExtensionW(path);
    if (ext && EqualsIgnoreCase(ext, L".accountpicture-ms")) {
        return LoadAccountPictureContainer(path);
    }
    auto* bmp = Gdiplus::Bitmap::FromFile(path, FALSE);
    if (bmp && bmp->GetLastStatus() == Gdiplus::Ok) {
        return bmp;
    }
    delete bmp;
    return LoadAccountPictureContainer(path);
}

static Gdiplus::Bitmap* GetUserPictureBitmap() {
    if (g.userPicBmp) {
        return g.userPicBmp;
    }
    if (g.sys.userPicture[0]) {
        g.userPicBmp = LoadUserPictureFile(g.sys.userPicture);
    }
    return g.userPicBmp;
}

static void DrawUserSilhouette(Gdiplus::Graphics& gr, const RECT& rc) {
    using namespace Gdiplus;
    SolidBrush bg(Color(255, 200, 206, 214));
    SolidBrush ink(Color(255, 90, 96, 104));
    const Rect r = ToG(rc);
    gr.FillRectangle(&bg, r);
    const int cx = r.X + r.Width / 2;
    const int head = IMax(4, r.Width / 4);
    gr.FillEllipse(&ink, cx - head, r.Y + r.Height / 5, head * 2, head * 2);
    gr.FillEllipse(&ink, r.X + r.Width / 6, r.Y + r.Height * 55 / 100,
                   r.Width * 2 / 3, r.Height);
}

