static Gdiplus::Bitmap* GetUserFrameBitmap() {
    return LoadModBitmap(g.userFrameBmp, L"user-frame", kUserFramePngB64);
}

// Well of kUserFramePngB64 as fractions of the 512px canvas.
static constexpr float kUserFrameWellL = 0.07422f;
static constexpr float kUserFrameWellT = 0.07422f;
static constexpr float kUserFrameWellR = 0.89453f;
static constexpr float kUserFrameWellB = 0.89453f;

static void DrawAeroUserTile(Gdiplus::Graphics& gr, const RECT& outer,
                             Gdiplus::Bitmap* photo) {
    using namespace Gdiplus;
    const REAL x = static_cast<REAL>(outer.left);
    const REAL y = static_cast<REAL>(outer.top);
    const REAL w = static_cast<REAL>(IMax(8, outer.right - outer.left));
    const REAL h = static_cast<REAL>(IMax(8, outer.bottom - outer.top));

    gr.SetSmoothingMode(SmoothingModeAntiAlias);
    gr.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    gr.SetCompositingQuality(CompositingQualityHighQuality);
    gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);

    const REAL ix = x + w * kUserFrameWellL;
    const REAL iy = y + h * kUserFrameWellT;
    const REAL iw = w * (kUserFrameWellR - kUserFrameWellL);
    const REAL ih = h * (kUserFrameWellB - kUserFrameWellT);
    {
        const GraphicsState st = gr.Save();
        gr.SetClip(RectF(ix, iy, iw, ih), CombineModeIntersect);
        RECT innerRc{static_cast<int>(ix), static_cast<int>(iy),
                     static_cast<int>(ix + iw + 0.5f),
                     static_cast<int>(iy + ih + 0.5f)};
        if (photo && photo->GetLastStatus() == Ok && photo->GetWidth() > 0 &&
            photo->GetHeight() > 0) {
            const int pw = static_cast<int>(photo->GetWidth());
            const int ph = static_cast<int>(photo->GetHeight());
            const REAL sx = iw / static_cast<REAL>(pw);
            const REAL sy = ih / static_cast<REAL>(ph);
            const REAL sc = (sx > sy) ? sx : sy;
            const REAL dw = static_cast<REAL>(pw) * sc;
            const REAL dh = static_cast<REAL>(ph) * sc;
            const REAL dx = ix + (iw - dw) * 0.5f;
            const REAL dy = iy + (ih - dh) * 0.5f;
            gr.DrawImage(photo, dx, dy, dw, dh);
        } else {
            DrawUserSilhouette(gr, innerRc);
        }
        gr.Restore(st);
    }

    if (Bitmap* frame = GetUserFrameBitmap()) {
        gr.DrawImage(frame, x, y, w, h);
    }
}

static void DrawHeaderBar(Gdiplus::Graphics& gr, const Layout& L) {
    using namespace Gdiplus;
    const Rect bar = ToG(L.userBar);
    if (bar.Width <= 0 || bar.Height <= 0) {
        return;
    }

    // Visible dark glass strip, not solid black and not invisible.
    LinearGradientBrush fill(Point(bar.X, bar.Y),
                             Point(bar.X, bar.Y + bar.Height),
                             Color(122, 0, 0, 0), Color(86, 0, 8, 12));
    gr.FillRectangle(&fill, bar);

    LinearGradientBrush fade(
        Point(bar.X, bar.Y + bar.Height - ScalePx(8, g.dpi)),
        Point(bar.X, bar.Y + bar.Height + ScalePx(1, g.dpi)),
        Color(40, 0, 0, 0), Color(0, 0, 0, 0));
    gr.FillRectangle(&fade, bar.X, bar.Y + bar.Height - ScalePx(8, g.dpi),
                     bar.Width, ScalePx(10, g.dpi));

    Pen top(Color(40, 255, 255, 255), 1);
    gr.DrawLine(&top, bar.X, bar.Y, bar.X + bar.Width, bar.Y);
    Pen bot(Color(70, 0, 0, 0), 1);
    gr.DrawLine(&bot, bar.X, bar.Y + bar.Height - 1, bar.X + bar.Width,
                bar.Y + bar.Height - 1);
}

