static Gdiplus::Bitmap* GetChevronBitmap() {
    return LoadModBitmap(g.chevronBmp, L"chevron", kAeroChevronPngB64);
}

static Gdiplus::Bitmap* GetGreenArrowBitmap() {
    return LoadModBitmap(g.greenArrowBmp, L"arrow", kGreenArrowPngB64);
}

static Gdiplus::Bitmap* GetOemLogoBitmap() {
    if (g.oemLogoBmp) {
        return g.oemLogoBmp;
    }
    if (!g.sys.oemLogo[0]) {
        return nullptr;
    }
    g.oemLogoBmp = Gdiplus::Bitmap::FromFile(g.sys.oemLogo, FALSE);
    if (!g.oemLogoBmp || g.oemLogoBmp->GetLastStatus() != Gdiplus::Ok) {
        delete g.oemLogoBmp;
        g.oemLogoBmp = nullptr;
    }
    return g.oemLogoBmp;
}

static void DrawOemLogo(Gdiplus::Graphics& gr, const Layout& L) {
    using namespace Gdiplus;
    Bitmap* logo = GetOemLogoBitmap();
    if (!logo || logo->GetWidth() == 0 || logo->GetHeight() == 0) {
        return;
    }
    const int boxW = IMax(1, L.oemLogo.right - L.oemLogo.left);
    const int boxH = IMax(1, L.oemLogo.bottom - L.oemLogo.top);
    if (boxW < 8 || boxH < 8) {
        return;
    }
    const REAL pw = static_cast<REAL>(logo->GetWidth());
    const REAL ph = static_cast<REAL>(logo->GetHeight());
    const REAL sx = static_cast<REAL>(boxW) / pw;
    const REAL sy = static_cast<REAL>(boxH) / ph;
    const REAL sc = (sx < sy) ? sx : sy;
    const REAL dw = pw * sc;
    const REAL dh = ph * sc;
    // Align toward the outer edge of the mirrored user bar.
    const REAL dx = IsRtlLanguage()
                        ? static_cast<REAL>(L.oemLogo.left)
                        : static_cast<REAL>(L.oemLogo.right) - dw;
    const REAL dy = static_cast<REAL>(L.oemLogo.top) +
                    (static_cast<REAL>(boxH) - dh) * 0.5f;
    gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    gr.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    gr.DrawImage(logo, dx, dy, dw, dh);
}

static const Item* PreviewItem() {
    int sec = -1;
    int idx = -1;
    if (g.selectedSection >= 0 && g.selectedIndex >= 0) {
        // A single click locks the preview. Hover is consulted only while no
        // item is selected, so moving across other tiles cannot replace it.
        sec = g.selectedSection;
        idx = g.selectedIndex;
    } else if (g.hoverSection >= 0 && g.hoverIndex >= 0) {
        sec = g.hoverSection;
        idx = g.hoverIndex;
    }
    if (sec < 0 || idx < 0) {
        return nullptr;
    }
    auto& items = ItemsOf(sec);
    if (idx >= static_cast<int>(items.size())) {
        return nullptr;
    }
    return &items[static_cast<size_t>(idx)];
}

static void HeaderPreviewId(int* sec, int* idx) {
    if (!sec || !idx) {
        return;
    }
    if (g.selectedSection >= 0 && g.selectedIndex >= 0) {
        auto& items = ItemsOf(g.selectedSection);
        if (g.selectedIndex < static_cast<int>(items.size())) {
            *sec = g.selectedSection;
            *idx = g.selectedIndex;
            return;
        }
    }
    if (g.hoverSection >= 0 && g.hoverIndex >= 0) {
        *sec = g.hoverSection;
        *idx = g.hoverIndex;
        return;
    }
    // -2/-2 means the default PC illustration and live system information.
    *sec = -2;
    *idx = -2;
}

static const Item* ItemAt(int sec, int idx) {
    if (sec < 0 || idx < 0) {
        return nullptr;
    }
    auto& items = ItemsOf(sec);
    if (idx >= static_cast<int>(items.size())) {
        return nullptr;
    }
    return &items[static_cast<size_t>(idx)];
}

static const wchar_t* ActionLabelFor(int sec, int idx) {
    const Item* it = ItemAt(sec, idx);
    if (!it) {
        return Ui(UiText::MoreAboutPc);
    }
    if (!it->actionLabel.empty()) {
        return it->actionLabel.c_str();
    }
    return it->title.c_str();
}

static void SyncHeaderAnim() {
    int sec = -2;
    int idx = -2;
    HeaderPreviewId(&sec, &idx);
    if (!g.headerAnimInited) {
        g.headerFromSec = g.headerToSec = sec;
        g.headerFromIdx = g.headerToIdx = idx;
        g.headerAnimInited = true;
        g.headerAnim = false;
        return;
    }
    if (sec == g.headerToSec && idx == g.headerToIdx) {
        return;
    }

    // If the pointer changes targets during a fade, continue from whichever
    // endpoint is currently dominant. This avoids snapping to the previous
    // target when the pointer moves quickly across adjacent tiles.
    int fromSec = g.headerToSec;
    int fromIdx = g.headerToIdx;
    if (g.headerAnim) {
        const DWORD elapsed = GetTickCount() - g.headerAnimStart;
        if (elapsed < kHeaderAnimMs && elapsed * 2 < kHeaderAnimMs) {
            fromSec = g.headerFromSec;
            fromIdx = g.headerFromIdx;
        }
    }

    g.headerFromSec = fromSec;
    g.headerFromIdx = fromIdx;
    g.headerToSec = sec;
    g.headerToIdx = idx;
    if (fromSec == sec && fromIdx == idx) {
        g.headerAnim = false;
        if (!g.headerIntro && g.main && IsWindow(g.main)) {
            KillTimer(g.main, kHeaderAnimTimerId);
        }
        return;
    }

    g.headerAnimStart = GetTickCount();
    g.headerAnim = true;
    if (g.main && IsWindow(g.main)) {
        SetTimer(g.main, kHeaderAnimTimerId, 16, nullptr);
    }
}

static void EnsureHeaderTimer() {
    if (g.main && IsWindow(g.main)) {
        SetTimer(g.main, kHeaderAnimTimerId, 16, nullptr);
    }
}

static void StartHeaderIntro() {
    g.headerIntro = true;
    g.headerIntroStart = GetTickCount();
    EnsureHeaderTimer();
}

static float HeaderIntroT() {
    if (!g.headerIntro) {
        return 1.0f;
    }
    const DWORD dt = GetTickCount() - g.headerIntroStart;
    float t = static_cast<float>(dt) / static_cast<float>(kHeaderIntroMs);
    if (t >= 1.0f) {
        return 1.0f;
    }
    if (t < 0.0f) {
        return 0.0f;
    }
    return t;
}

static float Smooth01(float t) {
    if (t <= 0.0f) {
        return 0.0f;
    }
    if (t >= 1.0f) {
        return 1.0f;
    }
    return t * t * (3.0f - 2.0f * t);
}

static float HeaderAnimT() {
    if (!g.headerAnim) {
        return 1.0f;
    }
    const DWORD dt = GetTickCount() - g.headerAnimStart;
    float t = static_cast<float>(dt) / static_cast<float>(kHeaderAnimMs);
    if (t >= 1.0f) {
        return 1.0f;
    }
    if (t < 0.0f) {
        return 0.0f;
    }
    // Smootherstep has zero velocity and acceleration at both ends. It keeps
    // the response quick while making the cross-fade settle more softly.
    return t * t * t * (t * (t * 6.0f - 15.0f) + 10.0f);
}

static void StopHeaderAnimIfDone() {
    if (!g.headerAnim) {
        return;
    }
    if (HeaderAnimT() < 1.0f) {
        return;
    }
    g.headerAnim = false;
    g.headerFromSec = g.headerToSec;
    g.headerFromIdx = g.headerToIdx;
    if (!g.headerIntro && g.main && IsWindow(g.main)) {
        KillTimer(g.main, kHeaderAnimTimerId);
    }
}

static void DrawItemPreview(Gdiplus::Graphics& gr, const Layout& L,
                            const Item& it) {
    using namespace Gdiplus;
    const int boxH = IMax(8, L.pcArt.bottom - L.pcArt.top);
    const int iconSz = IMin(ScalePx(108, g.dpi), boxH - ScalePx(4, g.dpi));
    const bool rtl = IsRtlLanguage();
    RECT iconRc{};
    iconRc.top = L.pcArt.top + IMax(0, (boxH - iconSz) / 2);
    iconRc.bottom = iconRc.top + iconSz;
    if (rtl) {
        iconRc.right = L.pcArt.right - ScalePx(12, g.dpi);
        iconRc.left = iconRc.right - iconSz;
    } else {
        iconRc.left = L.pcArt.left + ScalePx(12, g.dpi);
        iconRc.right = iconRc.left + iconSz;
    }
    DrawItemIcon(gr, it, iconRc);

    const wchar_t* title =
        !it.detailTitle.empty() ? it.detailTitle.c_str() : it.title.c_str();
    const wchar_t* body = !it.detailBody.empty() ? it.detailBody.c_str()
                                                 : it.description.c_str();

    const FontFamily* fam = GetSegoeFontFamily();
    Font titleFont(fam, 18.0f * static_cast<REAL>(g.dpi) / 96.0f,
                   FontStyleRegular, UnitPixel);
    Font bodyFont(fam, 9.5f * static_cast<REAL>(g.dpi) / 96.0f, FontStyleRegular,
                  UnitPixel);
    const bool win7 = IsWindows7Style();
    SolidBrush titleBr(win7 ? Color(255, 15, 30, 55)
                            : Color(255, 255, 255, 255));
    SolidBrush bodyBr(win7 ? Color(255, 20, 35, 58)
                           : Color(235, 255, 255, 255));
    SolidBrush titleSh(win7 ? Color(0, 0, 0, 0)
                            : Color(90, 0, 0, 0));

    const int textLeft = rtl ? L.showMore.right + ScalePx(12, g.dpi)
                             : iconRc.right + ScalePx(14, g.dpi);
    const int textRight = rtl ? iconRc.left - ScalePx(14, g.dpi)
                              : L.showMore.left - ScalePx(12, g.dpi);
    const REAL tx = static_cast<REAL>(textLeft);
    const REAL ty = static_cast<REAL>(L.userBarH + ScalePx(8, g.dpi));
    const REAL tw = static_cast<REAL>(IMax(40, textRight - textLeft));
    const REAL th = 24.0f * static_cast<REAL>(g.dpi) / 96.0f;
    StringFormat nearFmt;
    nearFmt.SetAlignment(StringAlignmentNear);
    nearFmt.SetLineAlignment(StringAlignmentNear);
    nearFmt.SetTrimming(StringTrimmingEllipsisCharacter);
    ApplyStringDirection(&nearFmt);
    RectF titleRc(tx, ty, tw, th);
    RectF tsh = titleRc;
    tsh.X += 1;
    tsh.Y += 1;
    gr.DrawString(title, -1, &titleFont, tsh, &nearFmt, &titleSh);
    gr.DrawString(title, -1, &titleFont, titleRc, &nearFmt, &titleBr);

    RectF bodyRc(tx, ty + th + 2.0f, tw,
                 static_cast<REAL>(L.header.bottom - ScalePx(8, g.dpi)) -
                     (ty + th + 2.0f));
    if (bodyRc.Height > 8.0f) {
        DrawStringG(gr, body, bodyFont, bodyBr, bodyRc, 0, true);
    }
}

static void DrawMoreAboutLink(Gdiplus::Graphics& gr, const Layout& L,
                             const wchar_t* label) {
    using namespace Gdiplus;
    if (!label || !*label) {
        label = Ui(UiText::MoreAboutPc);
    }
    const FontFamily* fam = GetSegoeFontFamily();
    if (IsWindows7Style()) {
        Font font(fam, 11.0f * static_cast<REAL>(g.dpi) / 96.0f,
                  FontStyleRegular, UnitPixel);
        SolidBrush textBr(g.hoverShowMore ? Color(255, 0, 82, 164)
                                          : Color(255, 18, 35, 62));
        RectF bounds((REAL)L.showMore.left, (REAL)L.showMore.top,
                     (REAL)IMax(8, L.showMore.right - L.showMore.left),
                     (REAL)IMax(8, L.showMore.bottom - L.showMore.top));
        RectF measured;
        gr.MeasureString(label, -1, &font, bounds, &measured);
        const REAL arrow = 17.0f * static_cast<REAL>(g.dpi) / 96.0f;
        const REAL gap = 7.0f * static_cast<REAL>(g.dpi) / 96.0f;
        const REAL total = arrow + gap + measured.Width;
        const REAL x = IsRtlLanguage()
                           ? static_cast<REAL>(L.showMore.left)
                           : static_cast<REAL>(L.showMore.right) - total;
        const REAL cy = static_cast<REAL>(L.showMore.top + L.showMore.bottom) * 0.5f;

        if (Bitmap* arrowBmp = GetGreenArrowBitmap()) {
            const REAL aw = arrow;
            const REAL ah = arrow * static_cast<REAL>(arrowBmp->GetHeight()) /
                            static_cast<REAL>(arrowBmp->GetWidth());
            const REAL top = cy - ah * 0.5f;
            gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
            if (IsRtlLanguage()) {
                PointF dest[3] = {PointF(x + aw, top), PointF(x, top),
                                  PointF(x + aw, top + ah)};
                gr.DrawImage(arrowBmp, dest, ARRAYSIZE(dest), 0.0f, 0.0f,
                             static_cast<REAL>(arrowBmp->GetWidth()),
                             static_cast<REAL>(arrowBmp->GetHeight()), UnitPixel);
            } else {
                gr.DrawImage(arrowBmp, x, top, aw, ah);
            }
        }

        StringFormat fmt;
        fmt.SetAlignment(StringAlignmentNear);
        fmt.SetLineAlignment(StringAlignmentCenter);
        fmt.SetFormatFlags(fmt.GetFormatFlags() | StringFormatFlagsNoWrap);
        fmt.SetTrimming(StringTrimmingEllipsisCharacter);
        ApplyStringDirection(&fmt);
        RectF tr(x + arrow + gap, (REAL)L.showMore.top,
                 (REAL)L.showMore.right - (x + arrow + gap),
                 (REAL)(L.showMore.bottom - L.showMore.top));
        gr.DrawString(label, -1, &font, tr, &fmt, &textBr);
        return;
    }
    Font font(fam, 11.0f * static_cast<REAL>(g.dpi) / 96.0f, FontStyleRegular,
              UnitPixel);
    SolidBrush textBr(g.hoverShowMore ? Color(255, 255, 255, 255)
                                      : Color(240, 255, 255, 255));

    RectF layout((REAL)L.showMore.left, (REAL)L.showMore.top,
                 (REAL)IMax(8, L.showMore.right - L.showMore.left),
                 (REAL)IMax(8, L.showMore.bottom - L.showMore.top));
    RectF textSize;
    gr.MeasureString(label, -1, &font, layout, &textSize);

    const REAL arrow = 14.0f * static_cast<REAL>(g.dpi) / 96.0f;
    const REAL gap = 6.0f * static_cast<REAL>(g.dpi) / 96.0f;
    const REAL total = arrow + gap + textSize.Width;
    const REAL x = IsRtlLanguage()
                       ? static_cast<REAL>(L.showMore.left)
                       : static_cast<REAL>(L.showMore.right) - total;
    const REAL cy = static_cast<REAL>(L.showMore.top + L.showMore.bottom) * 0.5f;

    if (Bitmap* ch = GetChevronBitmap()) {
        const REAL ah = arrow;
        const REAL aw = arrow;
        gr.SetInterpolationMode(InterpolationModeHighQualityBicubic);
        const REAL top = cy - ah * 0.5f;
        if (IsRtlLanguage()) {
            PointF dest[3] = {PointF(x + aw, top), PointF(x, top),
                              PointF(x + aw, top + ah)};
            gr.DrawImage(ch, dest, ARRAYSIZE(dest), 0.0f, 0.0f,
                         static_cast<REAL>(ch->GetWidth()),
                         static_cast<REAL>(ch->GetHeight()), UnitPixel);
        } else {
            gr.DrawImage(ch, x, top, aw, ah);
        }
    }

    StringFormat fmt;
    fmt.SetAlignment(StringAlignmentNear);
    fmt.SetLineAlignment(StringAlignmentCenter);
    fmt.SetFormatFlags(fmt.GetFormatFlags() | StringFormatFlagsNoWrap);
    fmt.SetTrimming(StringTrimmingEllipsisCharacter);
    ApplyStringDirection(&fmt);
    RectF tr(x + arrow + gap, static_cast<REAL>(L.showMore.top), textSize.Width + 4.0f,
             static_cast<REAL>(L.showMore.bottom - L.showMore.top));
    RectF tg = tr;
    tg.X += 1;
    tg.Y += 1;
    SolidBrush shadow(Color(80, 0, 0, 0));
    gr.DrawString(label, -1, &font, tg, &fmt, &shadow);
    gr.DrawString(label, -1, &font, tr, &fmt, &textBr);
}

static void DrawHeaderForeground(Gdiplus::Graphics& gr, const Layout& L,
                                 int sec, int idx) {
    using namespace Gdiplus;
    const Item* it = ItemAt(sec, idx);
    if (it) {
        DrawItemPreview(gr, L, *it);
        DrawMoreAboutLink(gr, L, ActionLabelFor(sec, idx));
        return;
    }
    DrawPcIllustration(gr, L.pcArt);
    const FontFamily* fam = GetSegoeFontFamily();
    wchar_t block[512];
    swprintf_s(block, L"%s\n%s\n%s\n%s\n%s: %s", g.sys.editionLine,
               g.sys.cpuName, g.sys.ramText, g.sys.gpuName,
               Ui(UiText::ComputerName), g.sys.computerName);
    if (IsWindows7Style()) {
        Font titleFont(fam, 18.0f * static_cast<REAL>(g.dpi) / 96.0f,
                       FontStyleRegular, UnitPixel);
        Font infoFont(fam, 9.0f * static_cast<REAL>(g.dpi) / 96.0f,
                      FontStyleRegular, UnitPixel);
        SolidBrush titleBr(Color(255, 15, 30, 55));
        SolidBrush infoBr(Color(255, 20, 35, 58));
        const REAL titleH = 25.0f * static_cast<REAL>(g.dpi) / 96.0f;
        DrawStringG(gr, Ui(UiText::GettingStartedWithWindows), titleFont,
                    titleBr,
                    RectF((REAL)L.info.left, (REAL)L.info.top,
                          (REAL)(L.info.right - L.info.left), titleH),
                    0, false);
        DrawStringG(gr, block, infoFont, infoBr,
                    RectF((REAL)L.info.left, (REAL)L.info.top + titleH + 2.0f,
                          (REAL)(L.info.right - L.info.left),
                          (REAL)(L.info.bottom - L.info.top) - titleH - 2.0f));
        DrawMoreAboutLink(gr, L, Ui(UiText::MoreAboutPc));
        return;
    }
    Font infoFont(fam, 9.0f * static_cast<REAL>(g.dpi) / 96.0f, FontStyleRegular,
                  UnitPixel);
    SolidBrush almost(Color(235, 255, 255, 255));
    DrawStringG(gr, block, infoFont, almost,
                RectF((REAL)L.info.left, (REAL)L.info.top,
                      (REAL)(L.info.right - L.info.left),
                      (REAL)(L.info.bottom - L.info.top)));
    DrawMoreAboutLink(gr, L, Ui(UiText::MoreAboutPc));
}

static void DrawHeaderForegroundAlpha(Gdiplus::Graphics& dest, const Layout& L,
                                      int sec, int idx, float alpha) {
    using namespace Gdiplus;
    if (alpha <= 0.02f) {
        return;
    }
    if (alpha >= 0.98f) {
        DrawHeaderForeground(dest, L, sec, idx);
        return;
    }
    const int w = L.header.right - L.header.left;
    const int h = L.header.bottom - L.header.top;
    if (w <= 0 || h <= 0) {
        return;
    }
    Bitmap layer(w, h, PixelFormat32bppARGB);
    if (layer.GetLastStatus() != Ok) {
        DrawHeaderForeground(dest, L, sec, idx);
        return;
    }
    Graphics lg(&layer);
    lg.SetSmoothingMode(SmoothingModeHighQuality);
    lg.SetInterpolationMode(InterpolationModeHighQualityBicubic);
    // ClearType assumes an opaque destination and produces colored fringes
    // when this transparent layer is alpha-blended. Grayscale antialiasing
    // keeps animated text clean and soft.
    lg.SetTextRenderingHint(TextRenderingHintAntiAliasGridFit);
    lg.SetPixelOffsetMode(PixelOffsetModeHighQuality);
    lg.Clear(Color(0, 0, 0, 0));
    lg.TranslateTransform(static_cast<REAL>(-L.header.left),
                          static_cast<REAL>(-L.header.top));
    DrawHeaderForeground(lg, L, sec, idx);

    ColorMatrix cm{};
    cm.m[0][0] = cm.m[1][1] = cm.m[2][2] = cm.m[4][4] = 1.0f;
    cm.m[3][3] = alpha;
    ImageAttributes attr;
    attr.SetColorMatrix(&cm, ColorMatrixFlagsDefault, ColorAdjustTypeBitmap);
    dest.DrawImage(&layer,
                   Rect(L.header.left, L.header.top, w, h),
                   0, 0, w, h, UnitPixel, &attr);
}

